-- ===============================================================================================
-- PART 9: insert_rows_resource_table.sql
-- demo human / material / expense / revenue roles; managementGenus on the role types
-- ===============================================================================================

-- =====================================================================================
-- UNIVERSAL1 - RESOURCE ROWS: insert_rows_resource_table.sql
-- Demo rows for the three kinds of resources of the management genus (kit8/catalog/resourcerole, kit8/catalog/management/genus):
--   1. Human Resources    (resourceRoleTypeTable.rowJSON.managementGenus = timeGenus)      5 roles: Project Manager, Business Analyst, Data Analyst,
--                                                                                         Frontend Developer, Backend Developer - hourly rates, Senior / Middle variants
--   2. Material Resources (materialGenus)                                                  10 roles: Wood plate 20x20, Birch plate 20x20, Oak board, plywood, steel profile,
--                                                                                         aluminium sheet, copper cable, wood screws, varnish, epoxy resin
--   3. Expense Resources  (expenseGenus)                                                   10 roles in the domains Logistic, Transport, Advertisement, Service
--   4. Revenue Resources  (revenueGenus)                                                   2 roles: Stage #1 Revenue, Stage #2 Revenue (a Bill rate each, per stage)
-- VAT: an empty VAT of a role type becomes 0 % (vat_0; a role with no VAT of its own uses its type's rate, so no resource is left without one).
-- VAT 21 % (vat_21): on every Material role itself and on both Revenue roles (roleVATRate); Human / Expense roles use the 21 % default of their role type.
-- Every human, material and expense role has a Bill rate (what the customer pays) and a Cost rate (what it costs the company) per ITS unit (hour, pcs, m, m2, l, kg, km, day, month).
-- Also sets managementGenus = timeGenus on the five role types of the sheet (projectManager ... backendDeveloper) when they have none.
--
-- RUN AFTER create_product_tables.sql, create_resource_role_tables.sql and create_management_genus_table.sql.
-- IDEMPOTENT + NON-DESTRUCTIVE: seeds ON CONFLICT DO NOTHING (a row you changed or deleted is left alone).
-- Rows: measureUnitTable 5, resourceRoleFolderTable 11, resourceRoleTypeTable 4, descriptorDestinationTable 2, descriptorPlanTable 4, variantTable 3, variantValueTable 6, resourceRoleTable 27, propertyValueTable 8, rolePriceTable 57
-- =====================================================================================

DO $$
BEGIN
  IF to_regclass('public."resourceRoleTypeTable"') IS NULL OR to_regclass('public."rolePriceTable"') IS NULL THEN
    RAISE EXCEPTION 'Run create_product_tables.sql and create_resource_role_tables.sql first';
  END IF;
  IF to_regclass('public."managementGenusTable"') IS NULL THEN
    RAISE EXCEPTION 'Run create_management_genus_table.sql first';
  END IF;
  IF (SELECT count(*) FROM public."managementGenusTable" WHERE "rowGUID" IN ('timeGenus', 'materialGenus', 'expenseGenus')) < 3 THEN
    RAISE EXCEPTION 'managementGenusTable has no timeGenus / materialGenus / expenseGenus: run create_management_genus_table.sql';
  END IF;
END $$;

-- the five role types of the sheet are time resources
UPDATE public."resourceRoleTypeTable"
   SET "rowJSON" = jsonb_set("rowJSON", '{managementGenus}', '"timeGenus"'::jsonb)
 WHERE "rowGUID" IN ('projectManager', 'businessAnalyst', 'dataAnalyst', 'frontendDeveloper', 'backendDeveloper')
   AND coalesce("rowJSON"->>'managementGenus', '') = '';
UPDATE public."resourceRoleTypeTable"
   SET "rowJSON" = jsonb_set("rowJSON", '{roleVATDefaultRate}', '"vat_0"'::jsonb)
 WHERE coalesce("rowJSON"->>'roleVATDefaultRate', '') = '';

-- the material roles carry VAT 21 % themselves (also when they were inserted by an earlier version of this script)
UPDATE public."resourceRoleTable"
   SET "rowJSON" = jsonb_set("rowJSON", '{roleVATRate}', '"vat_21"'::jsonb)
 WHERE "rowOwnerGUID" = 'materialResources' AND coalesce("rowJSON"->>'roleVATRate', '') = '';

NOTIFY pgrst, 'reload schema';

-- Check:
--   SELECT t."rowJSON"->>'title' AS role_type, t."rowJSON"->>'managementGenus' AS genus, count(r.*) AS roles
--     FROM public."resourceRoleTypeTable" t LEFT JOIN public."resourceRoleTable" r ON r."rowOwnerGUID" = t."rowGUID" GROUP BY 1, 2 ORDER BY 1;


-- ===============================================================================================
-- PART 10: create_person_type_table.sql
-- personTypeTable (Employee, Contractor) + 50 % Employee / 50 % Contractor of all persons
-- ===============================================================================================

-- =====================================================================================
-- UNIVERSAL1 - PERSON TYPES: create_person_type_table.sql
-- (Supabase / PostgreSQL 15+. Remove again with delete_person_type_table.sql. Run AFTER create_tables.sql (personTable) and
--  create_product_tables.sql (kit8_setup_def_table); the descriptor data is the next script: create_person_descriptors.sql.)
--
-- personTypeTable: the twin of productTypeTable / resourceRoleTypeTable for PEOPLE (sheet "W1 V3 ER DESCRIPTORS PLAN", rule R12):
--   Employee · Contractor. A type decides which descriptor sets (Property / Variant) its persons use - like a product type.
--   rowGUID = the code ('personTypeEmployee') · rowOwnerGUID 'personTypeCatalog' · rowParentGUID 'empty' · orderInList · rowJSON
--   rowJSON { title, description, propertySet, variantSet, variantMode ('perProduct' = the variants belong to the PERSON), uniqueVariants,
--             variantTitleTemplate, isActive }
-- The type of a person is personTable.rowJSON.personType (the owner of a person stays 'personCatalog': the Person screens and the
-- contracts keep working). personIsEmployee is kept in step with it (Employee = true).
--
-- Data: this script ALSO fills the demo persons so that 50 % are Employees and 50 % Contractors (every person without a type, by
-- order: odd = Employee, even = Contractor) and adds 6 demo persons when the catalog has fewer than 8.
-- IDEMPOTENT + NON-DESTRUCTIVE: CREATE ... IF NOT EXISTS, seeds ON CONFLICT DO NOTHING; a person that has a type keeps it.
-- =====================================================================================

DO $$
BEGIN
  IF to_regclass('public."personTable"') IS NULL OR to_regprocedure('public.kit8_setup_def_table(text)') IS NULL THEN
    RAISE EXCEPTION 'Run create_tables.sql and create_product_tables.sql first (personTable, kit8_setup_def_table)';
  END IF;
END $$;

CREATE TABLE IF NOT EXISTS public."personTypeTable" (
  "rowGUID"       TEXT        NOT NULL DEFAULT gen_random_uuid()::text,
  "rowOwnerGUID"  TEXT        NOT NULL DEFAULT 'personTypeCatalog',
  "rowParentGUID" TEXT        NOT NULL DEFAULT 'empty',
  "rowJSON"       JSONB       NOT NULL DEFAULT '{}'::jsonb,
  "orderInList"   NUMERIC     NOT NULL DEFAULT 0,
  "created_at"    TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  "updated_at"    TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  PRIMARY KEY ("rowGUID")
);
CREATE INDEX IF NOT EXISTS "idx_personTypeTable_owner_order" ON public."personTypeTable" ("rowOwnerGUID", "orderInList");
SELECT public.kit8_setup_def_table('personTypeTable');
CREATE INDEX IF NOT EXISTS "idx_personTable_type" ON public."personTable" (("rowJSON"->>'personType'));

-- access: signed-in users (as personTable)
REVOKE ALL ON public."personTypeTable" FROM anon, authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON public."personTypeTable" TO authenticated;
DROP POLICY IF EXISTS "personTypeTable_select" ON public."personTypeTable";
DROP POLICY IF EXISTS "personTypeTable_insert" ON public."personTypeTable";
DROP POLICY IF EXISTS "personTypeTable_update" ON public."personTypeTable";
DROP POLICY IF EXISTS "personTypeTable_delete" ON public."personTypeTable";
CREATE POLICY "personTypeTable_select" ON public."personTypeTable" FOR SELECT TO authenticated USING (true);
CREATE POLICY "personTypeTable_insert" ON public."personTypeTable" FOR INSERT TO authenticated WITH CHECK (true);
CREATE POLICY "personTypeTable_update" ON public."personTypeTable" FOR UPDATE TO authenticated USING (true) WITH CHECK (true);
CREATE POLICY "personTypeTable_delete" ON public."personTypeTable" FOR DELETE TO authenticated USING (true);

-- 50 % Employee / 50 % Contractor of ALL persons without a type: by order, odd = Employee, even = Contractor
WITH numbered AS (
  SELECT "rowGUID", row_number() OVER (ORDER BY "orderInList", "rowGUID") AS n, "rowJSON"->>'personType' AS current_type
    FROM public."personTable"
)
UPDATE public."personTable" p
   SET "rowJSON" = p."rowJSON" || jsonb_build_object(
         'personType', CASE WHEN n.n % 2 = 1 THEN 'personTypeEmployee' ELSE 'personTypeContractor' END,
         'personIsEmployee', n.n % 2 = 1)
  FROM numbered n
 WHERE p."rowGUID" = n."rowGUID" AND COALESCE(n.current_type, '') = '';

DO $$
DECLARE
  v_all boolean;
BEGIN
  SELECT puballtables INTO v_all FROM pg_publication WHERE pubname = 'supabase_realtime';
  IF NOT FOUND THEN
    RAISE NOTICE 'publication supabase_realtime does not exist - realtime auto refresh is off';
  ELSIF NOT v_all AND NOT EXISTS (SELECT 1 FROM pg_publication_tables WHERE pubname = 'supabase_realtime' AND schemaname = 'public' AND tablename = 'personTypeTable') THEN
    ALTER PUBLICATION supabase_realtime ADD TABLE public."personTypeTable";
  END IF;
END $$;

NOTIFY pgrst, 'reload schema';

-- Check:
--   SELECT "rowJSON"->>'personType' AS type, count(*) FROM public."personTable" GROUP BY 1;


-- ===============================================================================================
-- PART 11: create_person_descriptors.sql
-- person Properties + Variants (separate certificate rows), a contract for every person
-- ===============================================================================================

-- =====================================================================================
-- UNIVERSAL1 - PERSON DESCRIPTORS: create_person_descriptors.sql
-- (Supabase / PostgreSQL 15+. Remove again with delete_person_descriptors.sql.)
-- Run AFTER create_product_tables.sql, create_resource_role_tables.sql and create_person_type_table.sql.
--
-- A PERSON has his own Properties and Variants, built on the same descriptor tables as the products and the roles (sheet
-- "W1 V3 ER DESCRIPTORS PLAN", rule R12 mirrored for people). They are separate from the ones of a role:
--   role Property = what the role REQUIRES      person Property = what the person IS      (Experience 7 years, Certification PMP ...)
--   role Variant  = what is BOOKED (Senior, EN) person Variant  = what he CAN BE BOOKED AS (Senior, English)
-- The two sides meet on the DESCRIPTOR (descriptorGenus + descriptorValue are shared), not on the plan line: Seniority = Senior is the same
-- pair on both sides, although the plan lines (dp18 / dp_emp_v1) belong to different sets.
--
-- Rows added (all with fixed ids, ON CONFLICT DO NOTHING; IDEMPOTENT):
--   descriptorGenusTable        seniority / workLanguage / certification get targetKinds + 'personType' (rule R11); certification gets
--                               "multiple": true = a person has SEVERAL, each one is its own propertyValue row; new genus experienceYears
--                               (number; "satisfies": "minExperienceYears" = it answers the role requirement of that descriptor)
--   descriptorDestinationTable  ds_emp_prop / ds_emp_var (Employee), ds_con_prop / ds_con_var (Contractor)   owner = personType
--   descriptorPlanTable         Property: experienceYears (required), certification | Variant: seniority, workLanguage (both required)
--   propertyValueTable          per person: experience years + 1..3 SEPARATE certification rows           owner = person
--   variantTable / variantValueTable  per person: 1..2 variants (Seniority, Working language)            owner = person (variantMode perProduct)
--   contractTable               every person without an ACTIVE contract gets one: Employee = Employment (per Month), Contractor = Service (per Day)
-- The cost of a person on a task line comes from his contract (per hour = the sum of the period / the working hours of the period);
-- when the line has no contract the rate of the resource role is used (kit8/pm/view/task/finances/taskLineContractCost.ts).
-- =====================================================================================

DO $$
BEGIN
  IF to_regclass('public."personTypeTable"') IS NULL THEN RAISE EXCEPTION 'Run create_person_type_table.sql first'; END IF;
  IF to_regclass('public."resourceRoleTypeTable"') IS NULL THEN RAISE EXCEPTION 'Run create_resource_role_tables.sql first (the descriptors seniority, workLanguage, certification)'; END IF;
  IF to_regclass('public."contractTable"') IS NULL THEN RAISE EXCEPTION 'Run create_tables.sql first (contractTable)'; END IF;
END $$;

-- ---- several certificates = several rows of the SAME plan line: the unique index (owner, plan line) of propertyValueTable must allow it ----------------
-- (create_product_tables.sql now creates it with the list value in the key; a database made before keeps the old two-column index: replace it here)
DROP INDEX IF EXISTS public."idx_propertyValueTable_owner_plan";
CREATE UNIQUE INDEX IF NOT EXISTS "idx_propertyValueTable_owner_plan" ON public."propertyValueTable" ("rowOwnerGUID", "rowParentGUID", (coalesce("rowJSON"->>'descriptorValueGUID', ''))) WHERE "rowOwnerGUID" <> 'empty' AND "rowParentGUID" <> 'empty';

-- ---- descriptors (rule R11: the genus lists the kind of the owner of the set) ---------------------------------------------
UPDATE public."descriptorGenusTable" g
   SET "rowJSON" = jsonb_set(g."rowJSON", '{targetKinds}', COALESCE(g."rowJSON"->'targetKinds', '[]'::jsonb) || '"personType"'::jsonb)
 WHERE g."rowGUID" IN ('seniority', 'workLanguage', 'certification')
   AND NOT (COALESCE(g."rowJSON"->'targetKinds', '[]'::jsonb) ? 'personType');

-- several certifications = several rows (rule R8 is relaxed for a descriptor with "multiple": true)
UPDATE public."descriptorGenusTable" g SET "rowJSON" = g."rowJSON" || '{"multiple": true}'::jsonb WHERE g."rowGUID" = 'certification';

-- ---- values of every person --------------------------------------------------------------------------------------------------
-- Property: experience years (one row) + 1..3 certifications, each its OWN row on the same plan line (certification is "multiple")
WITH cfg AS (
  SELECT p."rowGUID" AS pg, row_number() OVER (ORDER BY p."orderInList", p."rowGUID") AS n,
         CASE WHEN p."rowJSON"->>'personType' = 'personTypeContractor' THEN 'dp_con_' ELSE 'dp_emp_' END AS pre
    FROM public."personTable" p
)
INSERT INTO public."propertyValueTable" ("rowGUID", "rowOwnerGUID", "rowParentGUID", "orderInList", "rowJSON")
SELECT 'pp_exp_' || pg, pg, pre || 'p1', 200000 + n, jsonb_build_object('value', 2 + (n * 3) % 9) FROM cfg
ON CONFLICT ("rowGUID") DO NOTHING;

WITH cfg AS (
  SELECT p."rowGUID" AS pg, row_number() OVER (ORDER BY p."orderInList", p."rowGUID") AS n,
         CASE WHEN p."rowJSON"->>'personType' = 'personTypeContractor' THEN 'dp_con_' ELSE 'dp_emp_' END AS pre
    FROM public."personTable" p
)
INSERT INTO public."propertyValueTable" ("rowGUID", "rowOwnerGUID", "rowParentGUID", "orderInList", "rowJSON")
SELECT 'pp_cert_' || pg || '_' || k, pg, pre || 'p2', 210000 + n * 10 + k,
       jsonb_build_object('descriptorValueGUID', (ARRAY['dv18', 'dv19', 'dv20', 'dv21'])[1 + ((n + k) % 4)])
  FROM cfg CROSS JOIN generate_series(1, 3) AS k
 WHERE k <= 1 + (n % 3)
ON CONFLICT ("rowGUID") DO NOTHING;

-- Variants: Seniority (Junior .. Lead by order) x English; every second person can also be booked in Latvian
WITH cfg AS (
  SELECT p."rowGUID" AS pg, row_number() OVER (ORDER BY p."orderInList", p."rowGUID") AS n,
         CASE WHEN p."rowJSON"->>'personType' = 'personTypeContractor' THEN 'dp_con_' ELSE 'dp_emp_' END AS pre
    FROM public."personTable" p
), combo AS (
  SELECT pg, n, pre, k,
         (ARRAY['dv11', 'dv12', 'dv13', 'dv14'])[1 + (n % 4)] AS sen,
         (ARRAY['Junior', 'Middle', 'Senior', 'Lead'])[1 + (n % 4)] AS sen_title,
         CASE k WHEN 1 THEN 'dv15' ELSE 'dv16' END AS lang,
         CASE k WHEN 1 THEN 'English' ELSE 'Latvian' END AS lang_title
    FROM cfg CROSS JOIN generate_series(1, 2) AS k
   WHERE k = 1 OR n % 2 = 0
)
INSERT INTO public."variantTable" ("rowGUID", "rowOwnerGUID", "rowParentGUID", "orderInList", "rowJSON")
SELECT 'pvar_' || pg || '_' || k, pg, 'empty', 220000 + n * 10 + k,
       jsonb_build_object('title', sen_title || ', ' || lang_title, 'descriptorKey', pre || 'v1=' || sen || '|' || pre || 'v2=' || lang, 'isActive', true)
  FROM combo
ON CONFLICT ("rowGUID") DO NOTHING;

WITH cfg AS (
  SELECT p."rowGUID" AS pg, row_number() OVER (ORDER BY p."orderInList", p."rowGUID") AS n,
         CASE WHEN p."rowJSON"->>'personType' = 'personTypeContractor' THEN 'dp_con_' ELSE 'dp_emp_' END AS pre
    FROM public."personTable" p
), combo AS (
  SELECT pg, n, pre, k,
         (ARRAY['dv11', 'dv12', 'dv13', 'dv14'])[1 + (n % 4)] AS sen,
         CASE k WHEN 1 THEN 'dv15' ELSE 'dv16' END AS lang
    FROM cfg CROSS JOIN generate_series(1, 2) AS k
   WHERE k = 1 OR n % 2 = 0
)
INSERT INTO public."variantValueTable" ("rowGUID", "rowOwnerGUID", "rowParentGUID", "orderInList", "rowJSON")
SELECT 'pvv_' || pg || '_' || k || '_' || part, 'pvar_' || pg || '_' || k, pre || CASE part WHEN 's' THEN 'v1' ELSE 'v2' END, 230000 + n * 10 + k,
       jsonb_build_object('descriptorValueGUID', CASE part WHEN 's' THEN sen ELSE lang END)
  FROM combo CROSS JOIN (VALUES ('s'), ('l')) AS parts(part)
ON CONFLICT ("rowGUID") DO NOTHING;

-- ---- a contract for every person without an ACTIVE one (the Time line of a task takes the cost from it) ------------------------
WITH cfg AS (
  SELECT p."rowGUID" AS pg, p."rowJSON"->>'personTitle' AS title, row_number() OVER (ORDER BY p."orderInList", p."rowGUID") AS n,
         (p."rowJSON"->>'personType') = 'personTypeContractor' AS contractor
    FROM public."personTable" p
   WHERE NOT EXISTS (SELECT 1 FROM public."contractTable" c
                      WHERE c."rowOwnerGUID" = p."rowGUID" AND c."rowParentGUID" = 'person' AND c."rowJSON"->>'contractStatus' = 'active')
), sums AS (
  SELECT *, CASE WHEN contractor THEN 160 + (n * 23) % 240 ELSE 2400 + (n * 350) % 3200 END AS amount FROM cfg
)
INSERT INTO public."contractTable" ("rowGUID", "rowOwnerGUID", "rowParentGUID", "orderInList", "rowJSON")
SELECT 'contract_' || pg, pg, 'person', -20454,
       jsonb_build_object(
         'contractPartyType', 'person',
         'contractNumber', CASE WHEN contractor THEN 'SRV-2026-' ELSE 'EMP-2026-' END || lpad(n::text, 3, '0'),
         'contractTitle', CASE WHEN contractor THEN 'Service agreement - ' ELSE 'Employment agreement - ' END || title,
         'contractType', CASE WHEN contractor THEN 'Service' ELSE 'Employment' END,
         'contractStatus', 'active', 'contractSignedDate', '2025-12-15', 'contractStartDate', '2026-01-01',
         'contractFinishDate', CASE WHEN contractor THEN to_jsonb('2026-12-31'::text) ELSE 'null'::jsonb END,
         'contractPaymentsPeriod', CASE WHEN contractor THEN 'Day' ELSE 'Month' END,
         'contractCurrency', 'EUR', 'contractSumBeforeVAT', amount, 'contractVATRate', 0, 'contractVAT', 0, 'contractTotal', amount,
         'notes', CASE WHEN contractor THEN 'Paid per working day' ELSE 'Paid per month' END)
  FROM sums
ON CONFLICT ("rowGUID") DO NOTHING;

NOTIFY pgrst, 'reload schema';

-- Check:
--   SELECT "rowJSON"->>'personType', count(*) FROM public."personTable" GROUP BY 1;
--   SELECT p."rowJSON"->>'personTitle', count(*) FILTER (WHERE v."rowParentGUID" LIKE '%p2') AS certificates
--     FROM public."personTable" p LEFT JOIN public."propertyValueTable" v ON v."rowOwnerGUID" = p."rowGUID" GROUP BY 1;


-- ===============================================================================================
-- PART 12: create_template_resource_contract_table.sql
-- templateResourceContractTable (rowOwnerGUID = management genus) + demo templates
-- ===============================================================================================

-- =====================================================================================
-- UNIVERSAL1 - TEMPLATE RESOURCE CONTRACT: create_template_resource_contract_table.sql
-- (Supabase / PostgreSQL 15+. Remove again with delete_template_resource_contract_table.sql. Run AFTER create_management_genus_table.sql.)
--
-- templateResourceContractTable: the TEMPLATE of the contract a task line asks for - the requirements for a resource, before any partner is
-- known ("for future supplies independent from Partner here", sheet "W1 TASK LINES"). A line (task_line_table) of Material / Expense /
-- Revenue points at a template with rowJSON.resourceContractTemplateTaskLine; when a partner is chosen later, a real contract (contractTable)
-- is made from the template. It works like a template for FUTURE partner relationships.
--   rowGUID        the template
--   rowOwnerGUID   managementGenusTable.rowGUID of a LEAF genus: timeGenus | materialGenus | expenseGenus | revenueGenus
--   rowParentGUID  'empty'
--   orderInList    order in the list
--   rowJSON        { title, description, requirements (the terms asked for), contractType, paymentsPeriod, paymentTermDays, currency, vatRate,
--                    deliveryTerms, validityDays, isActive }
-- The list of a task line is limited to the templates of ITS genus (task_line_table.rowJSON.taskManagementGenusLine).
-- Screen: TemplateResourceContractCRUD (kit8/catalog/management/templateresourcecontract), route /catalog/management/templateresourcecontract/list.
-- IDEMPOTENT + NON-DESTRUCTIVE: CREATE ... IF NOT EXISTS, seeds ON CONFLICT DO NOTHING.
-- =====================================================================================

DO $$
BEGIN
  IF to_regclass('public."managementGenusTable"') IS NULL OR to_regprocedure('public.kit8_setup_def_table(text)') IS NULL THEN
    RAISE EXCEPTION 'Run create_management_genus_table.sql first (managementGenusTable, kit8_setup_def_table)';
  END IF;
END $$;

CREATE TABLE IF NOT EXISTS public."templateResourceContractTable" (
  "rowGUID"       TEXT        NOT NULL DEFAULT gen_random_uuid()::text,
  "rowOwnerGUID"  TEXT        NOT NULL,
  "rowParentGUID" TEXT        NOT NULL DEFAULT 'empty',
  "rowJSON"       JSONB       NOT NULL DEFAULT '{}'::jsonb,
  "orderInList"   NUMERIC     NOT NULL DEFAULT 0,
  "created_at"    TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  "updated_at"    TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  PRIMARY KEY ("rowGUID"),
  CONSTRAINT "templateResourceContract_genus_chk" CHECK ("rowOwnerGUID" <> '' AND "rowOwnerGUID" <> 'empty'),
  CONSTRAINT "templateResourceContract_term_chk" CHECK (CASE
    WHEN jsonb_typeof("rowJSON"->'paymentTermDays') = 'number' THEN ("rowJSON"->>'paymentTermDays')::numeric >= 0
    ELSE "rowJSON"->'paymentTermDays' IS NULL OR jsonb_typeof("rowJSON"->'paymentTermDays') = 'null' END),
  CONSTRAINT "templateResourceContract_vat_chk" CHECK (CASE
    WHEN jsonb_typeof("rowJSON"->'vatRate') = 'number' THEN ("rowJSON"->>'vatRate')::numeric BETWEEN 0 AND 100
    ELSE "rowJSON"->'vatRate' IS NULL OR jsonb_typeof("rowJSON"->'vatRate') = 'null' END)
);
CREATE INDEX IF NOT EXISTS "idx_templateResourceContractTable_genus_order" ON public."templateResourceContractTable" ("rowOwnerGUID", "orderInList");
CREATE INDEX IF NOT EXISTS "idx_templateResourceContractTable_title" ON public."templateResourceContractTable" ((lower("rowJSON"->>'title')));
SELECT public.kit8_setup_def_table('templateResourceContractTable');

REVOKE ALL ON public."templateResourceContractTable" FROM anon, authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON public."templateResourceContractTable" TO authenticated;
DROP POLICY IF EXISTS "templateResourceContractTable_select" ON public."templateResourceContractTable";
DROP POLICY IF EXISTS "templateResourceContractTable_insert" ON public."templateResourceContractTable";
DROP POLICY IF EXISTS "templateResourceContractTable_update" ON public."templateResourceContractTable";
DROP POLICY IF EXISTS "templateResourceContractTable_delete" ON public."templateResourceContractTable";
CREATE POLICY "templateResourceContractTable_select" ON public."templateResourceContractTable" FOR SELECT TO authenticated USING (true);
CREATE POLICY "templateResourceContractTable_insert" ON public."templateResourceContractTable" FOR INSERT TO authenticated WITH CHECK (true);
CREATE POLICY "templateResourceContractTable_update" ON public."templateResourceContractTable" FOR UPDATE TO authenticated USING (true) WITH CHECK (true);
CREATE POLICY "templateResourceContractTable_delete" ON public."templateResourceContractTable" FOR DELETE TO authenticated USING (true);

DO $$
DECLARE
  v_all boolean;
BEGIN
  SELECT puballtables INTO v_all FROM pg_publication WHERE pubname = 'supabase_realtime';
  IF NOT FOUND THEN
    RAISE NOTICE 'publication supabase_realtime does not exist - realtime auto refresh is off';
  ELSIF NOT v_all AND NOT EXISTS (SELECT 1 FROM pg_publication_tables WHERE pubname = 'supabase_realtime' AND schemaname = 'public' AND tablename = 'templateResourceContractTable') THEN
    ALTER PUBLICATION supabase_realtime ADD TABLE public."templateResourceContractTable";
  END IF;
END $$;

NOTIFY pgrst, 'reload schema';


-- ===============================================================================================
-- PART 13: create_pm_task_line_table.sql
-- task_line_table + RPC pm_set_task_last_edit_place (rowJSON.lastEditPlace)
-- ===============================================================================================

-- =====================================================================================
-- UNIVERSAL1 - PM TASK LINES: create_pm_task_line_table.sql
-- (run AFTER create_tables.sql; IDEMPOTENT + NON-DESTRUCTIVE - safe to run twice.
--  Remove again with delete_pm_task_line_table.sql.)
--
-- task_line_table - the finance lines of ONE task, the same table for every management genus
-- (sheet "W1 TASK LINES"): Time (a role + a person), Material, Expense (a role + a product + a partner), Revenue.
--   rowGUID         the line
--   rowProjectGUID  project_table.rowGUID      (FK, filled by the trigger from the task - the app never sends it)
--   rowOwnerGUID    project_task_table.rowGUID (FK, cascade: a deleted task takes its lines with it)
--   rowParentGUID   managementGenusTable.rowGUID of a LEAF genus: timeGenus | materialGenus | expenseGenus | revenueGenus
--   orderInList     the order of the lines inside ONE genus of the task (drag & drop); "rowNumber" is not stored
--   rowJSON         resourceRoleItem            resourceRoleTable.rowGUID
--                   resourceRoleAttributeSetKey descriptorKey of the variant the role needs (Senior, remote ...)
--                   taskResourceItem            personTable.rowGUID (Time) | productTable.rowGUID (everything else)
--                   taskResourceAttributesKey   Time: descriptorKey of the VARIANT OF THE PERSON the line books (variantTable, owner = person)
--                                               | others: descriptorKey of the product variant
--                   taskManagementGenusLine     the genus of the line (= rowParentGUID, kept in step by the app: the templates offered depend on it)
--                   taskResourceContract        contractTable.rowGUID of the PERSON (Time lines only): the cost of the line comes from it
--                   resourceContractTemplateTaskLine  templateResourceContractTable.rowGUID (Material / Expense / Revenue): the contract asked for,
--                                               before a partner is known (create_template_resource_contract_table.sql)
--                   taskLinePartnerItem         partnerTable.rowGUID (Material / Expense / Revenue)
--                   taskLinePartnerContract     contractTable.rowGUID of that partner
--                   qtyTaskLine · priceTaskLine · measureUnitTaskLine (measureUnitTable.rowGUID)
--                   priceSourceTaskLine ('contract' | 'role' | 'product' | 'manual') · priceAutoTaskLine (the last price the app suggested: while
--                   priceTaskLine equals it the price follows the role / product, once the user types another one it stays)
--                   vatRatioTaskLine            percent (0..100)
--                   sumForContract = qty * price · sumVATForContract = sumForContract * vat / 100   (written by the app on every save)
--                   (sums in the accounting / budget currency come later: there is no budget in this version)
-- Titles are never copied: the app reads them from the catalogs.
--
-- Also here: RPC pm_set_task_last_edit_place - saves project_task_table.rowJSON.lastEditPlace (the place of the task the user edited
-- last) WITHOUT sending the rest of rowJSON, so it cannot overwrite the schedule write-back (rowJSON.startAt) or another edit.
-- =====================================================================================

CREATE TABLE IF NOT EXISTS public.task_line_table (
  "rowGUID"        UUID        NOT NULL DEFAULT gen_random_uuid(),
  "rowProjectGUID" UUID        NOT NULL REFERENCES public.project_table("rowGUID") ON DELETE CASCADE,
  "rowOwnerGUID"   UUID        NOT NULL REFERENCES public.project_task_table("rowGUID") ON DELETE CASCADE,
  "rowParentGUID"  TEXT        NOT NULL,
  "orderInList"    NUMERIC     NOT NULL DEFAULT 0,
  "rowJSON"        JSONB       NOT NULL DEFAULT '{}'::jsonb,
  "created_at"     TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  "updated_at"     TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  PRIMARY KEY ("rowGUID"),
  CONSTRAINT task_line_genus_chk CHECK ("rowParentGUID" <> '' AND "rowParentGUID" <> 'empty'),
  -- qty / price: empty (line not filled yet) or a number >= 0; VAT: empty or a number 0..100 (CASE: the cast only runs on a number)
  CONSTRAINT task_line_qty_chk CHECK (CASE
    WHEN jsonb_typeof("rowJSON"->'qtyTaskLine') = 'number' THEN ("rowJSON"->>'qtyTaskLine')::numeric >= 0
    ELSE "rowJSON"->'qtyTaskLine' IS NULL OR jsonb_typeof("rowJSON"->'qtyTaskLine') = 'null' END),
  CONSTRAINT task_line_price_chk CHECK (CASE
    WHEN jsonb_typeof("rowJSON"->'priceTaskLine') = 'number' THEN ("rowJSON"->>'priceTaskLine')::numeric >= 0
    ELSE "rowJSON"->'priceTaskLine' IS NULL OR jsonb_typeof("rowJSON"->'priceTaskLine') = 'null' END),
  CONSTRAINT task_line_vat_chk CHECK (CASE
    WHEN jsonb_typeof("rowJSON"->'vatRatioTaskLine') = 'number' THEN ("rowJSON"->>'vatRatioTaskLine')::numeric BETWEEN 0 AND 100
    ELSE "rowJSON"->'vatRatioTaskLine' IS NULL OR jsonb_typeof("rowJSON"->'vatRatioTaskLine') = 'null' END),
  -- a contract of the resource / partner needs the resource / partner
  CONSTRAINT task_line_partner_contract_chk CHECK (
    COALESCE("rowJSON"->>'taskLinePartnerContract', '') = '' OR COALESCE("rowJSON"->>'taskLinePartnerItem', '') <> '')
);

CREATE INDEX IF NOT EXISTS idx_task_line_task_genus ON public.task_line_table ("rowOwnerGUID", "rowParentGUID", "orderInList");
CREATE INDEX IF NOT EXISTS idx_task_line_project    ON public.task_line_table ("rowProjectGUID");
CREATE INDEX IF NOT EXISTS idx_task_line_role       ON public.task_line_table (("rowJSON"->>'resourceRoleItem'));
CREATE INDEX IF NOT EXISTS idx_task_line_resource   ON public.task_line_table (("rowJSON"->>'taskResourceItem'));
CREATE INDEX IF NOT EXISTS idx_task_line_rowJSON    ON public.task_line_table USING GIN ("rowJSON" jsonb_path_ops);

-- updated_at
DROP TRIGGER IF EXISTS trg_task_line_touch ON public.task_line_table;
CREATE TRIGGER trg_task_line_touch BEFORE UPDATE ON public.task_line_table
  FOR EACH ROW EXECUTE FUNCTION public.pm_touch_updated_at();

-- the project of a line is the project of its task (the app sends rowOwnerGUID = task only; a task cannot be moved to another project)
CREATE OR REPLACE FUNCTION public.task_line_set_project() RETURNS trigger
LANGUAGE plpgsql SET search_path = public, extensions AS $$
DECLARE
  v_project uuid;
BEGIN
  SELECT t."projectGUID" INTO v_project FROM public.project_task_table t WHERE t."rowGUID" = NEW."rowOwnerGUID";
  IF v_project IS NULL THEN
    RAISE EXCEPTION 'task % does not exist', NEW."rowOwnerGUID" USING ERRCODE = '23503';
  END IF;
  NEW."rowProjectGUID" := v_project;
  RETURN NEW;
END;
$$;
DROP TRIGGER IF EXISTS trg_task_line_set_project ON public.task_line_table;
CREATE TRIGGER trg_task_line_set_project
  BEFORE INSERT OR UPDATE OF "rowOwnerGUID" ON public.task_line_table
  FOR EACH ROW EXECUTE FUNCTION public.task_line_set_project();

-- realtime needs the whole old row on DELETE
ALTER TABLE public.task_line_table REPLICA IDENTITY FULL;

-- access: the owner of the project only
ALTER TABLE public.task_line_table ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.task_line_table FROM anon, authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.task_line_table TO authenticated;
DROP POLICY IF EXISTS task_line_select ON public.task_line_table;
DROP POLICY IF EXISTS task_line_insert ON public.task_line_table;
DROP POLICY IF EXISTS task_line_update ON public.task_line_table;
DROP POLICY IF EXISTS task_line_delete ON public.task_line_table;
CREATE POLICY task_line_select ON public.task_line_table FOR SELECT TO authenticated
  USING (public.pm_owns_project("rowProjectGUID"));
CREATE POLICY task_line_insert ON public.task_line_table FOR INSERT TO authenticated
  WITH CHECK (public.pm_owns_project("rowProjectGUID"));
CREATE POLICY task_line_update ON public.task_line_table FOR UPDATE TO authenticated
  USING (public.pm_owns_project("rowProjectGUID")) WITH CHECK (public.pm_owns_project("rowProjectGUID"));
CREATE POLICY task_line_delete ON public.task_line_table FOR DELETE TO authenticated
  USING (public.pm_owns_project("rowProjectGUID"));

-- realtime: other browsers / devices see the lines at once
DO $$
DECLARE
  v_all boolean;
BEGIN
  SELECT puballtables INTO v_all FROM pg_publication WHERE pubname = 'supabase_realtime';
  IF NOT FOUND THEN
    RAISE NOTICE 'publication supabase_realtime does not exist - realtime auto refresh is off';
  ELSIF NOT v_all AND NOT EXISTS (SELECT 1 FROM pg_publication_tables
                                   WHERE pubname = 'supabase_realtime' AND schemaname = 'public' AND tablename = 'task_line_table') THEN
    ALTER PUBLICATION supabase_realtime ADD TABLE public.task_line_table;
  END IF;
END $$;

-- -------------------------------------------------------------------------------------
-- RPC: the place of the task the user edited last (rowJSON.lastEditPlace); p_place NULL removes it.
-- SECURITY INVOKER: the RLS policies of project_task_table decide who may write.
-- -------------------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.pm_set_task_last_edit_place(p_task_guid uuid, p_place jsonb) RETURNS integer
LANGUAGE plpgsql SECURITY INVOKER SET search_path = public, extensions AS $$
DECLARE
  v_count integer;
BEGIN
  UPDATE public.project_task_table t
     SET "rowJSON" = CASE WHEN p_place IS NULL OR jsonb_typeof(p_place) = 'null'
                          THEN t."rowJSON" - 'lastEditPlace'
                          ELSE jsonb_set(t."rowJSON", '{lastEditPlace}', p_place, true) END
   WHERE t."rowGUID" = p_task_guid;
  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END;
$$;
GRANT EXECUTE ON FUNCTION public.pm_set_task_last_edit_place(uuid, jsonb) TO authenticated;

NOTIFY pgrst, 'reload schema';


-- ===============================================================================================
-- PART 14: create_management_calendar_tables.sql
-- management calendars (Project / Resource role / Person folders), their days, fill_management_calendar, the default Working days calendar
-- ===============================================================================================

-- =====================================================================================
-- UNIVERSAL1 - MANAGEMENT CALENDARS: create_management_calendar_tables.sql
-- (Supabase / PostgreSQL 15+. Remove again with delete_management_calendar_tables.sql.)
--
-- managementCalendarTable: the calendars of the business, two levels in one table (the shape of managementGenusTable / budgetItemTable):
--   FOLDERS   (level 1, rowParentGUID 'empty')   projectCalendarFolder · resourceRoleCalendarFolder · personCalendarFolder
--   CALENDARS (level 2, rowParentGUID = folder)  projectCalendarFolder > workingDaysCalendar  (the default: Mon-Fri, no holidays)
--   rowGUID (TEXT = the code) · rowOwnerGUID 'managementCalendarCatalog' (the business - the abstract entity; no business table exists yet)
--   rowParentGUID (folder | 'empty') · orderInList · rowJSON { title, description }
--
-- managementCalendarDaysTable: ONE ROW PER CALENDAR DAY of a calendar:
--   rowGUID       '<calendar rowGUID>:<YYYY-MM-DD>'  (so a fill is an idempotent upsert)
--   rowOwnerGUID  managementCalendarTable.rowGUID
--   rowParentGUID the YEAR as text ('2026'): a table of one calendar and one year is a page of at most 366 rows
--   orderInList   the day as a number (days since 1970-01-01)
--   rowJSON       { day: 'YYYY-MM-DD', isActive: boolean, reason: 'fill' | 'weekend' | 'holiday' | 'manual', note }
-- isActive=false = the day is EXCLUDED (the calendar does not work on it): a task plan gets no row and no money for it.
-- The user excludes (or includes) any day by switching isActive (reason becomes 'manual', so a later Fill does not overwrite it unless asked).
--
-- fill_management_calendar(calendar, year, mode, overwrite_manual, hours, follow_project_holidays) writes a whole year in one statement:
--   mode 'workingDays' Mon-Fri active, Sat+Sun off; days flagged 'holiday' stay off
--        'fiveDays'    Mon-Fri active, Sat+Sun off (holiday flags are cleared)
--        'sixDays'     Mon-Sat active, Sun off
--        'allDays'     all 7 days active
--   Days with reason 'manual' are kept unless p_overwrite_manual is true.
-- The default calendar workingDaysCalendar is filled for the previous, the current and the next year (only when it has no days yet).
-- project_table.rowJSON.calendarForTaskPlan = the calendar that divides the timeline of a task plan (default workingDaysCalendar).
-- Screen: Management calendars (kit8/catalog/management/calendar, route /catalog/management/calendar/list).
-- IDEMPOTENT + NON-DESTRUCTIVE: CREATE ... IF NOT EXISTS, seeds ON CONFLICT DO NOTHING.
-- =====================================================================================

CREATE EXTENSION IF NOT EXISTS pgcrypto;

CREATE OR REPLACE FUNCTION public.kit8_touch_updated_at() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  NEW."updated_at" := NOW();
  RETURN NEW;
END;
$$;

-- one helper for every catalog / generic table: RLS on + touch trigger + REPLICA IDENTITY FULL
CREATE OR REPLACE FUNCTION public.kit8_setup_def_table(p_table text) RETURNS void
LANGUAGE plpgsql AS $$
BEGIN
  EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY', p_table);
  EXECUTE format('ALTER TABLE public.%I REPLICA IDENTITY FULL', p_table);
  EXECUTE format('DROP TRIGGER IF EXISTS set_updated_at_trigger ON public.%I', p_table);
  EXECUTE format('DROP TRIGGER IF EXISTS %I ON public.%I', 'trg_' || p_table || '_touch', p_table);
  EXECUTE format('CREATE TRIGGER %I BEFORE UPDATE ON public.%I FOR EACH ROW EXECUTE FUNCTION public.kit8_touch_updated_at()',
                 'trg_' || p_table || '_touch', p_table);
  EXECUTE format('CREATE INDEX IF NOT EXISTS %I ON public.%I USING GIN ("rowJSON" jsonb_path_ops)', 'idx_' || p_table || '_rowJSON', p_table);
  EXECUTE format('CREATE INDEX IF NOT EXISTS %I ON public.%I ("orderInList")', 'idx_' || p_table || '_order', p_table);
END;
$$;

CREATE TABLE IF NOT EXISTS public."managementCalendarTable" (
  "rowGUID"       TEXT        NOT NULL DEFAULT gen_random_uuid()::text,
  "rowOwnerGUID"  TEXT        NOT NULL DEFAULT 'managementCalendarCatalog',
  "rowParentGUID" TEXT        NOT NULL DEFAULT 'empty',
  "rowJSON"       JSONB       NOT NULL DEFAULT '{}'::jsonb,
  "orderInList"   NUMERIC     NOT NULL DEFAULT 0,
  "created_at"    TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  "updated_at"    TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  PRIMARY KEY ("rowGUID")
);
CREATE INDEX IF NOT EXISTS "idx_managementCalendarTable_owner_order" ON public."managementCalendarTable" ("rowOwnerGUID", "orderInList");
CREATE INDEX IF NOT EXISTS "idx_managementCalendarTable_parent" ON public."managementCalendarTable" ("rowParentGUID");
SELECT public.kit8_setup_def_table('managementCalendarTable');

CREATE TABLE IF NOT EXISTS public."managementCalendarDaysTable" (
  "rowGUID"       TEXT        NOT NULL,
  "rowOwnerGUID"  TEXT        NOT NULL REFERENCES public."managementCalendarTable"("rowGUID") ON DELETE CASCADE,
  "rowParentGUID" TEXT        NOT NULL DEFAULT 'empty',
  "rowJSON"       JSONB       NOT NULL DEFAULT '{}'::jsonb,
  "orderInList"   NUMERIC     NOT NULL DEFAULT 0,
  "created_at"    TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  "updated_at"    TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  PRIMARY KEY ("rowGUID"),
  CONSTRAINT management_calendar_day_chk CHECK (
    "rowJSON"->>'day' ~ '^\d{4}-\d{2}-\d{2}$' AND jsonb_typeof("rowJSON"->'isActive') = 'boolean')
);
CREATE INDEX IF NOT EXISTS "idx_managementCalendarDaysTable_owner_order" ON public."managementCalendarDaysTable" ("rowOwnerGUID", "orderInList");
CREATE UNIQUE INDEX IF NOT EXISTS "idx_managementCalendarDaysTable_owner_day" ON public."managementCalendarDaysTable" ("rowOwnerGUID", ("rowJSON"->>'day'));
SELECT public.kit8_setup_def_table('managementCalendarDaysTable');

-- security: full CRUD for signed-in users (as managementGenusTable)
DO $$
DECLARE
  t text;
BEGIN
  FOREACH t IN ARRAY ARRAY['managementCalendarTable', 'managementCalendarDaysTable'] LOOP
    EXECUTE format('REVOKE ALL ON public.%I FROM anon, authenticated', t);
    EXECUTE format('GRANT SELECT, INSERT, UPDATE, DELETE ON public.%I TO authenticated', t);
    EXECUTE format('DROP POLICY IF EXISTS %I ON public.%I', t || '_select', t);
    EXECUTE format('DROP POLICY IF EXISTS %I ON public.%I', t || '_insert', t);
    EXECUTE format('DROP POLICY IF EXISTS %I ON public.%I', t || '_update', t);
    EXECUTE format('DROP POLICY IF EXISTS %I ON public.%I', t || '_delete', t);
    EXECUTE format('CREATE POLICY %I ON public.%I FOR SELECT TO authenticated USING (true)', t || '_select', t);
    EXECUTE format('CREATE POLICY %I ON public.%I FOR INSERT TO authenticated WITH CHECK (true)', t || '_insert', t);
    EXECUTE format('CREATE POLICY %I ON public.%I FOR UPDATE TO authenticated USING (true) WITH CHECK (true)', t || '_update', t);
    EXECUTE format('CREATE POLICY %I ON public.%I FOR DELETE TO authenticated USING (true)', t || '_delete', t);
  END LOOP;
END $$;

-- -------------------------------------------------------------------------------------
-- the version before PART 21 had four arguments: with the new defaults a call with four would be ambiguous, so it goes
DROP FUNCTION IF EXISTS public.fill_management_calendar(text, integer, text, boolean);
-- fill_management_calendar: one year of days in one statement. Returns the number of day rows written.
--   p_mode   workingDays | fiveDays | sixDays | allDays   (the week modes)  ·  pattern = the hours of each weekday from the calendar's rowJSON.weekPattern {mon..sun} (a custom week)
--   p_hours  hours of an active day. NULL = the calendar's hoursPerDay for a RESOURCE calendar (rowJSON.kind = 'resource'), and NO hours at all for a project calendar (it is unchanged)
--   p_follow_project_holidays  (resource calendars) the days that the project calendars of the user's organization flag as holidays become holidays (reason holiday, 0 h)
--   A day row of a resource calendar carries rowJSON.hours (0 = not active); the exception days (reason vacation, holiday, manual ...) are kept unless p_overwrite_manual.
--   The calendar lock (PART 23) runs on every row written, so a Fill that would lower the capacity under posted hours is refused as a whole.
CREATE OR REPLACE FUNCTION public.fill_management_calendar(
  p_calendar text, p_year integer, p_mode text, p_overwrite_manual boolean DEFAULT false,
  p_hours numeric DEFAULT NULL, p_follow_project_holidays boolean DEFAULT false
) RETURNS integer
LANGUAGE plpgsql SECURITY INVOKER SET search_path = public, extensions AS $$
DECLARE
  v_count    integer;
  v_cal      jsonb;
  v_resource boolean;
  v_hours    numeric;
  v_days     text[] := ARRAY['mon', 'tue', 'wed', 'thu', 'fri', 'sat', 'sun'];
  v_holidays date[] := ARRAY[]::date[];
BEGIN
  IF p_mode NOT IN ('workingDays', 'fiveDays', 'sixDays', 'allDays', 'pattern') THEN
    RAISE EXCEPTION 'fill_management_calendar: unknown mode "%" (workingDays | fiveDays | sixDays | allDays | pattern)', p_mode;
  END IF;
  IF p_year < 1970 OR p_year > 2200 THEN
    RAISE EXCEPTION 'fill_management_calendar: year % is out of range', p_year;
  END IF;
  SELECT c."rowJSON" INTO v_cal FROM public."managementCalendarTable" c WHERE c."rowGUID" = p_calendar AND c."rowParentGUID" <> 'empty';
  IF NOT FOUND THEN
    RAISE EXCEPTION 'fill_management_calendar: calendar "%" does not exist (or is a folder)', p_calendar;
  END IF;
  v_resource := COALESCE(v_cal->>'kind', '') = 'resource';
  IF p_hours IS NOT NULL AND (p_hours < 0 OR p_hours > 24) THEN
    RAISE EXCEPTION 'fill_management_calendar: hours % are out of range (0 - 24)', p_hours;
  END IF;
  IF p_mode = 'pattern' AND jsonb_typeof(v_cal->'weekPattern') IS DISTINCT FROM 'object' THEN
    RAISE EXCEPTION 'fill_management_calendar: calendar "%" has no weekPattern (rowJSON.weekPattern {"mon": 8, ...})', p_calendar;
  END IF;
  IF p_follow_project_holidays AND NOT v_resource THEN
    RAISE EXCEPTION 'fill_management_calendar: "follow project holidays" is for resource calendars only';
  END IF;
  v_hours := COALESCE(p_hours, CASE WHEN v_resource THEN COALESCE((v_cal->>'hoursPerDay')::numeric, 8) END);
  IF p_follow_project_holidays THEN
    SELECT COALESCE(array_agg(h), ARRAY[]::date[]) INTO v_holidays FROM public.organization_holiday_days(public.organization_of_current_user(), p_year) AS h;
  END IF;

  INSERT INTO public."managementCalendarDaysTable" AS t ("rowGUID", "rowOwnerGUID", "rowParentGUID", "orderInList", "rowJSON")
  SELECT p_calendar || ':' || to_char(f.d, 'YYYY-MM-DD'), p_calendar, p_year::text, (f.d - DATE '1970-01-01')::numeric,
         jsonb_strip_nulls(jsonb_build_object(
           'day', to_char(f.d, 'YYYY-MM-DD'),
           'isActive', f.active,
           'reason', CASE WHEN f.holiday THEN 'holiday'
                          WHEN NOT f.active AND (p_mode = 'pattern' OR (p_mode = 'sixDays' AND f.dow = 7) OR (p_mode IN ('workingDays', 'fiveDays') AND f.dow >= 6)) THEN 'weekend'
                          ELSE 'fill' END,
           'hours', CASE WHEN NOT f.active THEN CASE WHEN v_hours IS NULL AND p_mode <> 'pattern' THEN NULL ELSE 0 END ELSE f.hrs END))
    FROM (SELECT g.d, g.dow, g.holiday,
                 g.active_mode AND NOT g.holiday AND (p_mode <> 'pattern' OR COALESCE(g.pat, 0) > 0) AS active,
                 CASE WHEN p_mode = 'pattern' THEN g.pat ELSE v_hours END AS hrs
            FROM (SELECT s.d, extract(isodow FROM s.d)::integer AS dow,
                         s.d = ANY (v_holidays) AS holiday,
                         CASE p_mode WHEN 'allDays' THEN true WHEN 'sixDays' THEN extract(isodow FROM s.d) <= 6 WHEN 'pattern' THEN true ELSE extract(isodow FROM s.d) <= 5 END AS active_mode,
                         (v_cal->'weekPattern'->>(v_days[extract(isodow FROM s.d)::integer]))::numeric AS pat
                    FROM (SELECT make_date(p_year, 1, 1) + i AS d
                            FROM generate_series(0, make_date(p_year, 12, 31) - make_date(p_year, 1, 1)) AS q(i)) AS s) AS g) AS f
  ON CONFLICT ("rowGUID") DO UPDATE
     SET "rowJSON" = EXCLUDED."rowJSON", "orderInList" = EXCLUDED."orderInList", "rowParentGUID" = EXCLUDED."rowParentGUID"
   WHERE (p_overwrite_manual OR COALESCE(t."rowJSON"->>'reason', '') NOT IN ('manual', 'vacation', 'sickLeave', 'training', 'other'))
     AND NOT (p_mode = 'workingDays' AND COALESCE(t."rowJSON"->>'reason', '') = 'holiday' AND NOT p_follow_project_holidays);
  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END;
$$;
GRANT EXECUTE ON FUNCTION public.fill_management_calendar(text, integer, text, boolean, numeric, boolean) TO authenticated;

-- the default calendar: previous, current and next year (only when it has no days yet - a second run changes nothing)
DO $$
DECLARE
  y integer := extract(year FROM current_date)::integer;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM public."managementCalendarDaysTable" WHERE "rowOwnerGUID" = 'workingDaysCalendar') THEN
    PERFORM public.fill_management_calendar('workingDaysCalendar', y - 1, 'workingDays');
    PERFORM public.fill_management_calendar('workingDaysCalendar', y,     'workingDays');
    PERFORM public.fill_management_calendar('workingDaysCalendar', y + 1, 'workingDays');
  END IF;
END $$;

-- realtime: both tables in the supabase_realtime publication
DO $$
DECLARE
  v_all boolean;
  t text;
BEGIN
  SELECT puballtables INTO v_all FROM pg_publication WHERE pubname = 'supabase_realtime';
  IF NOT FOUND THEN
    RAISE NOTICE 'publication supabase_realtime does not exist - realtime auto refresh is off';
    RETURN;
  END IF;
  IF v_all THEN
    RETURN;
  END IF;
  FOREACH t IN ARRAY ARRAY['managementCalendarTable', 'managementCalendarDaysTable'] LOOP
    IF NOT EXISTS (SELECT 1 FROM pg_publication_tables WHERE pubname = 'supabase_realtime' AND schemaname = 'public' AND tablename = t) THEN
      EXECUTE format('ALTER PUBLICATION supabase_realtime ADD TABLE public.%I', t);
    END IF;
  END LOOP;
END $$;

NOTIFY pgrst, 'reload schema';

-- Check:
--   SELECT "rowGUID", "rowParentGUID", "rowJSON"->>'title' FROM public."managementCalendarTable" ORDER BY "orderInList";
--   SELECT count(*), count(*) FILTER (WHERE ("rowJSON"->>'isActive')::boolean) FROM public."managementCalendarDaysTable" WHERE "rowOwnerGUID" = 'workingDaysCalendar';


-- ===============================================================================================
-- PART 15: create_task_line_plan_table.sql
-- task_line_plan (the posted days of the task lines) + task_line_plan_timeline (the same grouped by day) + RPC create_task_line_plan (one transaction, Correct033) + the unpost trigger
-- ===============================================================================================

-- =====================================================================================
-- UNIVERSAL1 - TASK LINE PLAN: create_task_line_plan_table.sql
-- (run AFTER create_pm_task_line_table.sql; IDEMPOTENT + NON-DESTRUCTIVE. Remove again with delete_task_line_plan_table.sql.)
--
-- task_line_plan - the POSTED days of the task lines: one row per line and active calendar day (document "W1 Post Task", Part 1.2).
--   rowProjectGUID     project_table.rowGUID      = task.rowProjectGUID   (FK, cascade)
--   rowOwnerGUID       project_task_table.rowGUID = task.rowGUID          (FK, cascade)
--   rowParentGUID      task_line_table.rowGUID    = the LINE the day belongs to (FK, cascade: a deleted line takes its days with it)
--   orderInList        (position of the line in the call) * 100000 + the day number: the lines one after the other, each by date
--   rowPeriodDatetime  the start of the day (00:00:00) - unique with the line
--   rowCoefficient     the share of the day, NORMALIZED: the coefficients of a line add up to baseOfDistribution (1)
--   qtyTaskLine · sumForBudget · sumForContract · sumForAccounting     the result of the distribution, rounded to 2 digits
--   rowJSON            { budgetItemTaskLine, taskManagementGenusLine, taskResourceKind, businessUnitAssigned, budgetKind } copied from the line, so a report needs no join
--                      (taskResourceKind: 'person' | 'equipment' of a Time line, null = a person or not a Time line;
--                       businessUnitAssigned = the business unit of the line (businessUnitTable.rowGUID, null = none), budgetKind = 'cost' | 'revenue' of its budget item -
--                       the unit is kept ON THE POSTED DAYS, so a later change of the line does not rewrite what was posted; PART 18)
-- The app only READS this table. Rows are written by ONE procedure, in ONE transaction:
--   create_task_line_plan("taskLinePlanJSON")   (see below)
--
-- Correct033 effect (document "0333 Effect"): every row is rounded on its own, so 100.00 split on 3 equal days gives 33.33 + 33.33 + 33.33 = 99.99.
-- The procedure adds the difference (original - distributed: +0.01 here) to the LAST row of the distribution (the last day with a non-zero
-- coefficient) -> 33.33 + 33.33 + 33.34 = 100.00. The same for rowCoefficient against baseOfDistribution (10 digits).
--
-- Also here: a trigger on project_task_table - when the start or the finish DAY of a task changes, its posted lines get taskIsPosted = false
-- ("Post needed"); the old rows stay until the next post.
-- =====================================================================================

DO $$
BEGIN
  IF to_regclass('public.task_line_table') IS NULL THEN
    RAISE EXCEPTION 'Run create_pm_task_line_table.sql first (task_line_plan points at task_line_table)';
  END IF;
END $$;

CREATE TABLE IF NOT EXISTS public.task_line_plan_movements (
  "rowGUID"           UUID          NOT NULL DEFAULT gen_random_uuid(),
  "rowProjectGUID"    UUID          NOT NULL REFERENCES public.project_table("rowGUID") ON DELETE CASCADE,
  "rowOwnerGUID"      UUID          NOT NULL REFERENCES public.project_task_table("rowGUID") ON DELETE CASCADE,
  "rowParentGUID"     UUID          NOT NULL REFERENCES public.task_line_table("rowGUID") ON DELETE CASCADE,
  "orderInList"       NUMERIC       NOT NULL DEFAULT 0,
  "rowPeriodDatetime" TIMESTAMPTZ   NOT NULL,
  "rowCoefficient"    NUMERIC(14,10) NOT NULL,
  "qtyTaskLine"       NUMERIC(18,2),
  "sumForBudget"      NUMERIC(18,2),
  "sumForContract"    NUMERIC(18,2),
  "sumForAccounting"  NUMERIC(18,2),
  "rowJSON"           JSONB         NOT NULL DEFAULT '{}'::jsonb,
  "created_at"        TIMESTAMPTZ   NOT NULL DEFAULT NOW(),
  "updated_at"        TIMESTAMPTZ   NOT NULL DEFAULT NOW(),
  "planMovementStatus" BOOLEAN      NOT NULL DEFAULT true,
  "periodDay"         DATE,
  PRIMARY KEY ("rowGUID"),
  CONSTRAINT task_line_plan_movements_coefficient_chk CHECK ("rowCoefficient" >= 0),
  CONSTRAINT task_line_plan_movements_line_period_uq UNIQUE ("rowParentGUID", "rowPeriodDatetime")
);
-- PART 22 (time genus control): planMovementStatus = false while the capacity check of Post is pending (the row is out of the reports, the timeline and the occupancy), true after it passed;
-- EVERY other movement is created with true (the default: no migration, every old row is true). periodDay = the day of the row in the zone of the post (rows of older posts are filled once).
-- sumForAccounting: the sum of the line in the ACCOUNTING currency of the project (task_line_table.rowJSON.sumForAccounting, taskLineFx.ts), distributed like sumForBudget; a database made before has the column added here
ALTER TABLE public.task_line_plan_movements ADD COLUMN IF NOT EXISTS "sumForAccounting" NUMERIC(18,2);
ALTER TABLE public.task_line_plan_movements ADD COLUMN IF NOT EXISTS "planMovementStatus" BOOLEAN NOT NULL DEFAULT true;
ALTER TABLE public.task_line_plan_movements ADD COLUMN IF NOT EXISTS "periodDay" DATE;
UPDATE public.task_line_plan_movements SET "periodDay" = (("rowPeriodDatetime" + INTERVAL '12 hours') AT TIME ZONE 'UTC')::date WHERE "periodDay" IS NULL;
CREATE INDEX IF NOT EXISTS idx_task_line_plan_movements_task    ON public.task_line_plan_movements ("rowOwnerGUID", "rowPeriodDatetime");
CREATE INDEX IF NOT EXISTS idx_task_line_plan_movements_project ON public.task_line_plan_movements ("rowProjectGUID", "rowPeriodDatetime");

DROP TRIGGER IF EXISTS trg_task_line_plan_movements_touch ON public.task_line_plan_movements;
CREATE TRIGGER trg_task_line_plan_movements_touch BEFORE UPDATE ON public.task_line_plan_movements
  FOR EACH ROW EXECUTE FUNCTION public.pm_touch_updated_at();

ALTER TABLE public.task_line_plan_movements REPLICA IDENTITY FULL;

-- access: the owner of the project READS; nobody writes directly (no insert / update / delete policy) - only create_task_line_plan does
ALTER TABLE public.task_line_plan_movements ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.task_line_plan_movements FROM anon, authenticated;
GRANT SELECT ON public.task_line_plan_movements TO authenticated;
DROP POLICY IF EXISTS task_line_plan_movements_select ON public.task_line_plan_movements;
CREATE POLICY task_line_plan_movements_select ON public.task_line_plan_movements FOR SELECT TO authenticated
  USING (public.pm_owns_project("rowProjectGUID"));

-- realtime
DO $$
DECLARE
  v_all boolean;
BEGIN
  SELECT puballtables INTO v_all FROM pg_publication WHERE pubname = 'supabase_realtime';
  IF NOT FOUND THEN
    RAISE NOTICE 'publication supabase_realtime does not exist - realtime auto refresh is off';
  ELSIF NOT v_all AND NOT EXISTS (SELECT 1 FROM pg_publication_tables
                                   WHERE pubname = 'supabase_realtime' AND schemaname = 'public' AND tablename = 'task_line_plan_movements') THEN
    ALTER PUBLICATION supabase_realtime ADD TABLE public.task_line_plan_movements;
  END IF;
END $$;

-- -------------------------------------------------------------------------------------
-- task_line_plan_timeline - the posted days of task_line_plan_movements GROUPED BY DAY (the tab "Timeline" of the Budgets view of a task).
--   rowProjectGUID / rowOwnerGUID   as in task_line_plan_movements (the project and the task; FK, cascade)
--   rowPeriodDatetime               the DAY, always: the start of the day (00:00:00 in the zone of the post) - unique with the line
--   taskLineGUID                    task_line_table.rowGUID (FK, cascade: a deleted line takes its days with it)
--   qtyForBudget                    the sum of task_line_plan_movements.qtyTaskLine of the line on that day
--   sumForContract · sumForBudget · sumForAccounting   the sums of the same columns of the movements
-- The app only READS it. The rows are created by create_task_line_plan (the Post of a task): the earlier rows of the task are replaced in the same
-- transaction, so the timeline always equals the movements.
-- -------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.task_line_plan_timeline (
  "rowGUID"           UUID          NOT NULL DEFAULT gen_random_uuid(),
  "rowProjectGUID"    UUID          NOT NULL REFERENCES public.project_table("rowGUID") ON DELETE CASCADE,
  "rowOwnerGUID"      UUID          NOT NULL REFERENCES public.project_task_table("rowGUID") ON DELETE CASCADE,
  "rowPeriodDatetime" TIMESTAMPTZ   NOT NULL,
  "taskLineGUID"      UUID          NOT NULL REFERENCES public.task_line_table("rowGUID") ON DELETE CASCADE,
  "qtyForBudget"      NUMERIC(18,2),
  "sumForContract"    NUMERIC(18,2),
  "sumForBudget"      NUMERIC(18,2),
  "sumForAccounting"  NUMERIC(18,2),
  "created_at"        TIMESTAMPTZ   NOT NULL DEFAULT NOW(),
  "updated_at"        TIMESTAMPTZ   NOT NULL DEFAULT NOW(),
  PRIMARY KEY ("rowGUID"),
  CONSTRAINT task_line_plan_timeline_line_day_uq UNIQUE ("taskLineGUID", "rowPeriodDatetime")
);
ALTER TABLE public.task_line_plan_timeline ADD COLUMN IF NOT EXISTS "sumForAccounting" NUMERIC(18,2);      -- a database made before has the column added here
CREATE INDEX IF NOT EXISTS idx_task_line_plan_timeline_task    ON public.task_line_plan_timeline ("rowOwnerGUID", "rowPeriodDatetime");
CREATE INDEX IF NOT EXISTS idx_task_line_plan_timeline_project ON public.task_line_plan_timeline ("rowProjectGUID", "rowPeriodDatetime");

DROP TRIGGER IF EXISTS trg_task_line_plan_timeline_touch ON public.task_line_plan_timeline;
CREATE TRIGGER trg_task_line_plan_timeline_touch BEFORE UPDATE ON public.task_line_plan_timeline
  FOR EACH ROW EXECUTE FUNCTION public.pm_touch_updated_at();

ALTER TABLE public.task_line_plan_timeline REPLICA IDENTITY FULL;

ALTER TABLE public.task_line_plan_timeline ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.task_line_plan_timeline FROM anon, authenticated;
GRANT SELECT ON public.task_line_plan_timeline TO authenticated;
DROP POLICY IF EXISTS task_line_plan_timeline_select ON public.task_line_plan_timeline;
CREATE POLICY task_line_plan_timeline_select ON public.task_line_plan_timeline FOR SELECT TO authenticated
  USING (public.pm_owns_project("rowProjectGUID"));

DO $$
DECLARE
  v_all boolean;
BEGIN
  SELECT puballtables INTO v_all FROM pg_publication WHERE pubname = 'supabase_realtime';
  IF NOT FOUND THEN
    RAISE NOTICE 'publication supabase_realtime does not exist - realtime auto refresh is off';
  ELSIF NOT v_all AND NOT EXISTS (SELECT 1 FROM pg_publication_tables
                                   WHERE pubname = 'supabase_realtime' AND schemaname = 'public' AND tablename = 'task_line_plan_timeline') THEN
    ALTER PUBLICATION supabase_realtime ADD TABLE public.task_line_plan_timeline;
  END IF;
END $$;

-- days posted before this table existed: one row per line and day (the movements are already one per line and day, each at the start of its day)
INSERT INTO public.task_line_plan_timeline ("rowProjectGUID", "rowOwnerGUID", "rowPeriodDatetime", "taskLineGUID", "qtyForBudget", "sumForContract", "sumForBudget", "sumForAccounting")
SELECT m."rowProjectGUID", m."rowOwnerGUID", m."rowPeriodDatetime", m."rowParentGUID", SUM(m."qtyTaskLine"), SUM(m."sumForContract"), SUM(m."sumForBudget"), SUM(m."sumForAccounting")
  FROM public.task_line_plan_movements m
 GROUP BY m."rowProjectGUID", m."rowOwnerGUID", m."rowParentGUID", m."rowPeriodDatetime"
ON CONFLICT ("taskLineGUID", "rowPeriodDatetime") DO NOTHING;

-- -------------------------------------------------------------------------------------
-- RPC create_task_line_plan("taskLinePlanJSON") - ONE transaction: replaces the posted days of a task.
--
--   { "taskGUID": "<uuid>",
--     "timeZone": "UTC",                                  -- optional: the zone the day starts in (default UTC)
--     "lines": [ { "lineGUID": "<uuid>", "baseOfDistribution": 1,
--                  "qtyTaskLine": 10, "sumForBudget": 100, "sumForContract": 100, "sumForAccounting": 100,       -- the totals of the line (null = none)
--                  "days": [ { "d": "2026-10-12", "c": 0.3333333333 }, ... ] } ] }       -- the days and their coefficients
--
-- Steps: lock the task and check the owner -> validate -> delete the earlier rows of the task -> insert round(total * c, 2) per day ->
-- Correct033 (last row) for the coefficients and the three amounts -> verify the totals -> taskIsPosted = true + baseOfDistribution on the lines.
-- Any error rolls EVERYTHING back. SECURITY DEFINER because the app has no write policy on task_line_plan; the owner of the project is checked first.
-- Returns { "lines": n, "rows": n }.
-- -------------------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.create_task_line_plan("taskLinePlanJSON" jsonb) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, extensions AS $$
DECLARE
  v_task     uuid;
  v_project  uuid;
  v_tz       text;
  v_line     jsonb;
  v_guid     uuid;
  v_ids      uuid[] := ARRAY[]::uuid[];
  v_days     jsonb;
  v_n        integer;
  v_base     numeric;
  v_csum     numeric;
  v_last     uuid;
  v_genus    text;
  v_item     jsonb;
  v_ljson    jsonb;
  v_unit     text;
  v_kind     text;
  v_col      text;
  v_total    numeric;
  v_sum      numeric;
  v_diff     numeric;
  v_rows     integer := 0;
  v_idx      integer := 0;
  v_org      text;
  v_mode     text;
  v_check    boolean;
  v_busy     jsonb := '[]'::jsonb;
  v_busy_lines uuid[] := ARRAY[]::uuid[];
  r          record;
BEGIN
  IF "taskLinePlanJSON" IS NULL OR jsonb_typeof("taskLinePlanJSON") <> 'object' THEN
    RAISE EXCEPTION 'create_task_line_plan: taskLinePlanJSON must be an object';
  END IF;
  v_task := ("taskLinePlanJSON"->>'taskGUID')::uuid;
  v_tz   := COALESCE(NULLIF("taskLinePlanJSON"->>'timeZone', ''), 'UTC');

  -- lock the task (two Post presses cannot interleave) and check the owner
  SELECT t."projectGUID" INTO v_project FROM public.project_task_table t WHERE t."rowGUID" = v_task FOR UPDATE;
  IF v_project IS NULL OR NOT public.pm_owns_project(v_project) THEN
    RAISE EXCEPTION 'create_task_line_plan: task % does not exist or is not yours', v_task USING ERRCODE = '42501';
  END IF;
  IF jsonb_typeof("taskLinePlanJSON"->'lines') <> 'array' THEN
    RAISE EXCEPTION 'create_task_line_plan: "lines" must be an array';
  END IF;

  -- the capacity check (PART 22): the mode of the ORGANIZATION of the project. capacityModeOff (the default, also a project without an organization) = exactly as before.
  SELECT p."rowParentGUID", COALESCE(NULLIF(o."rowJSON"->>'resourceCapacityStrongMode', ''), 'capacityModeOff')
    INTO v_org, v_mode
    FROM public.project_table p LEFT JOIN public."organizationTable" o ON o."rowGUID" = p."rowParentGUID" WHERE p."rowGUID" = v_project;
  v_mode  := COALESCE(v_mode, 'capacityModeOff');
  v_check := v_mode <> 'capacityModeOff' AND v_org IS NOT NULL;
  IF v_check THEN
    -- the calendars of the resources, SHARED (a change of one of these calendars waits for this Post), then one lock per resource, both in sorted order (no deadlock)
    FOR r IN SELECT DISTINCT cal FROM (SELECT DISTINCT COALESCE(NULLIF(l."rowJSON"->>'taskResourceKind', ''), 'person') AS k, l."rowJSON"->>'taskResourceItem' AS g
                                         FROM public.task_line_table l
                                        WHERE l."rowOwnerGUID" = v_task AND l."rowParentGUID" = 'timeGenus' AND COALESCE(l."rowJSON"->>'taskResourceItem', '') <> '') x,
                                      LATERAL public.organization_resource_calendars(x.k, x.g) AS cal
              ORDER BY 1 LOOP
      PERFORM public.organization_lock_calendar(r.cal, true);
    END LOOP;
    -- one lock per resource of the Time lines, in sorted order (no deadlock): a second Post or a change of a calendar of the same resource waits until this one is committed
    FOR r IN SELECT DISTINCT COALESCE(NULLIF(l."rowJSON"->>'taskResourceKind', ''), 'person') AS k, l."rowJSON"->>'taskResourceItem' AS g
               FROM public.task_line_table l
              WHERE l."rowOwnerGUID" = v_task AND l."rowParentGUID" = 'timeGenus' AND COALESCE(l."rowJSON"->>'taskResourceItem', '') <> ''
              ORDER BY 1, 2 LOOP
      PERFORM public.organization_lock_resource(r.k, r.g);
    END LOOP;
  END IF;

  -- the earlier days of the task are replaced
  DELETE FROM public.task_line_plan_movements WHERE "rowOwnerGUID" = v_task;
  DELETE FROM public.task_line_plan_timeline WHERE "rowOwnerGUID" = v_task;

  FOR v_line IN SELECT value FROM jsonb_array_elements("taskLinePlanJSON"->'lines') LOOP
    v_guid := (v_line->>'lineGUID')::uuid;
    v_idx  := v_idx + 1;
    SELECT l."rowParentGUID", jsonb_build_object('budgetItemTaskLine', l."rowJSON"->'budgetItemTaskLine', 'taskManagementGenusLine', l."rowParentGUID",
                                                 'taskResourceKind', COALESCE(l."rowJSON"->'taskResourceKind', 'null'::jsonb)), l."rowJSON"
      INTO v_genus, v_item, v_ljson
      FROM public.task_line_table l WHERE l."rowGUID" = v_guid AND l."rowOwnerGUID" = v_task;
    IF v_genus IS NULL THEN
      RAISE EXCEPTION 'create_task_line_plan: line % is not a line of task %', v_guid, v_task;
    END IF;

    -- the business unit of the line (PART 18): its kind = the folder of the genus of the budget item (costsGenus -> 'cost', revenuesGenus -> 'revenue'),
    -- else of the genus of the line. A line without a unit is posted as before. A cost on a revenue center (or a revenue on a cost center) is REFUSED.
    v_unit := NULLIF(v_ljson->>'businessUnitTaskLine', '');
    SELECT CASE gf."rowGUID" WHEN 'costsGenus' THEN 'cost' WHEN 'revenuesGenus' THEN 'revenue' END INTO v_kind
      FROM public."budgetItemTable" bi
      JOIN public."managementGenusTable" g  ON g."rowGUID"  = bi."rowJSON"->>'managementGenusItem'
      JOIN public."managementGenusTable" gf ON gf."rowGUID" = g."rowParentGUID"
     WHERE bi."rowGUID" = v_ljson->>'budgetItemTaskLine';
    IF v_kind IS NULL THEN
      SELECT CASE gf."rowGUID" WHEN 'costsGenus' THEN 'cost' WHEN 'revenuesGenus' THEN 'revenue' END INTO v_kind
        FROM public."managementGenusTable" g JOIN public."managementGenusTable" gf ON gf."rowGUID" = g."rowParentGUID" WHERE g."rowGUID" = v_genus;
    END IF;
    IF v_unit IS NOT NULL THEN
      IF NOT EXISTS (SELECT 1 FROM public."businessUnitTable" b WHERE b."rowGUID" = v_unit) THEN
        RAISE EXCEPTION 'create_task_line_plan: line % has the business unit "%" that does not exist', v_guid, v_unit;
      END IF;
      IF NOT public.kit8_cfr_accepts(public.kit8_business_unit_cfr(v_unit), v_kind) THEN
        RAISE EXCEPTION 'create_task_line_plan: line % (a % line) cannot be posted to the business unit "%" - a %', v_guid, v_kind, v_unit,
                        COALESCE((SELECT c."rowJSON"->>'title' FROM public."cfrTypeTable" c WHERE c."rowGUID" = public.kit8_business_unit_cfr(v_unit)), 'unit without a CFR');
      END IF;
    END IF;
    v_item := v_item || jsonb_build_object('businessUnitAssigned', to_jsonb(v_unit), 'budgetKind', to_jsonb(v_kind));

    v_days := v_line->'days';
    IF jsonb_typeof(v_days) <> 'array' OR jsonb_array_length(v_days) = 0 THEN
      RAISE EXCEPTION 'create_task_line_plan: line % has no days', v_guid;
    END IF;
    v_n    := jsonb_array_length(v_days);
    v_base := COALESCE((v_line->>'baseOfDistribution')::numeric, 1);
    IF v_base <= 0 THEN RAISE EXCEPTION 'create_task_line_plan: baseOfDistribution of line % must be > 0', v_guid; END IF;

    SELECT COALESCE(SUM(round((e.value->>'c')::numeric, 10)), 0) INTO v_csum FROM jsonb_array_elements(v_days) e;
    IF abs(v_csum - v_base) > 0.000001 THEN
      RAISE EXCEPTION 'create_task_line_plan: the coefficients of line % add up to %, not to %', v_guid, v_csum, v_base;
    END IF;
    IF EXISTS (SELECT 1 FROM jsonb_array_elements(v_days) e WHERE (e.value->>'c')::numeric < 0) THEN
      RAISE EXCEPTION 'create_task_line_plan: a coefficient of line % is negative', v_guid;
    END IF;

    -- one row per day: coefficient rounded to 10 digits, amounts = round(total * coefficient, 2) (null total = null amount)
    INSERT INTO public.task_line_plan_movements ("rowProjectGUID", "rowOwnerGUID", "rowParentGUID", "orderInList", "rowPeriodDatetime", "rowCoefficient",
                                       "qtyTaskLine", "sumForBudget", "sumForContract", "sumForAccounting", "rowJSON", "planMovementStatus", "periodDay")
    SELECT v_project, v_task, v_guid, v_idx * 100000 + e.ord,
           ((e.value->>'d')::date)::timestamp AT TIME ZONE v_tz,
           round((e.value->>'c')::numeric, 10),
           CASE WHEN jsonb_typeof(v_line->'qtyTaskLine')       = 'number' THEN round((v_line->>'qtyTaskLine')::numeric       * round((e.value->>'c')::numeric, 10), 2) END,
           CASE WHEN jsonb_typeof(v_line->'sumForBudget')      = 'number' THEN round((v_line->>'sumForBudget')::numeric      * round((e.value->>'c')::numeric, 10), 2) END,
           CASE WHEN jsonb_typeof(v_line->'sumForContract')    = 'number' THEN round((v_line->>'sumForContract')::numeric    * round((e.value->>'c')::numeric, 10), 2) END,
           CASE WHEN jsonb_typeof(v_line->'sumForAccounting')  = 'number' THEN round((v_line->>'sumForAccounting')::numeric  * round((e.value->>'c')::numeric, 10), 2) END,
           v_item,
           -- false = waits for the capacity check (only a Time line with a resource); every other row is active at once
           NOT (v_check AND v_genus = 'timeGenus' AND COALESCE(v_ljson->>'taskResourceItem', '') <> ''),
           (e.value->>'d')::date
      FROM jsonb_array_elements(v_days) WITH ORDINALITY AS e(value, ord);
    v_rows := v_rows + v_n;

    -- ---- Correct033: the last row of the distribution = the last day with a non-zero coefficient (else the last day) ----
    SELECT p."rowGUID" INTO v_last FROM public.task_line_plan_movements p
     WHERE p."rowParentGUID" = v_guid ORDER BY (p."rowCoefficient" > 0) DESC, p."rowPeriodDatetime" DESC LIMIT 1;

    SELECT v_base - COALESCE(SUM("rowCoefficient"), 0) INTO v_diff FROM public.task_line_plan_movements WHERE "rowParentGUID" = v_guid;
    IF v_diff <> 0 THEN
      UPDATE public.task_line_plan_movements SET "rowCoefficient" = "rowCoefficient" + v_diff WHERE "rowGUID" = v_last;
    END IF;

    FOREACH v_col IN ARRAY ARRAY['qtyTaskLine', 'sumForBudget', 'sumForContract', 'sumForAccounting'] LOOP
      IF jsonb_typeof(v_line->v_col) <> 'number' THEN CONTINUE; END IF;
      v_total := round((v_line->>v_col)::numeric, 2);
      EXECUTE format('SELECT COALESCE(SUM(%I), 0) FROM public.task_line_plan_movements WHERE "rowParentGUID" = $1', v_col) INTO v_sum USING v_guid;
      v_diff := v_total - v_sum;
      -- the rounding of n rows cannot lose more than n * 0.005: more is a bug, not a rounding
      IF abs(v_diff) > v_n * 0.005 + 0.000001 THEN
        RAISE EXCEPTION 'create_task_line_plan: % of line % differs by % after rounding (more than % rows can lose)', v_col, v_guid, v_diff, v_n;
      END IF;
      IF v_diff <> 0 THEN
        EXECUTE format('UPDATE public.task_line_plan_movements SET %I = %I + $1 WHERE "rowGUID" = $2', v_col, v_col) USING v_diff, v_last;
      END IF;
      -- verify
      EXECUTE format('SELECT COALESCE(SUM(%I), 0) FROM public.task_line_plan_movements WHERE "rowParentGUID" = $1', v_col) INTO v_sum USING v_guid;
      IF v_sum <> v_total THEN
        RAISE EXCEPTION 'create_task_line_plan: % of line % adds up to %, not to %', v_col, v_guid, v_sum, v_total;
      END IF;
    END LOOP;
    SELECT COALESCE(SUM("rowCoefficient"), 0) INTO v_sum FROM public.task_line_plan_movements WHERE "rowParentGUID" = v_guid;
    IF v_sum <> v_base THEN
      RAISE EXCEPTION 'create_task_line_plan: the coefficients of line % add up to %, not to %', v_guid, v_sum, v_base;
    END IF;

    v_ids := v_ids || v_guid;
  END LOOP;

  -- the capacity check (after Correct033, so it sees the final hours): every busy line is REPORTED. capacityModeBlock also deletes its rows and leaves it unposted ("Post needed");
  -- capacityModeWarn keeps them. A conflict is an answer, not an exception: an exception would roll the deletion back too.
  IF v_check THEN
    FOR r IN SELECT * FROM public.organization_resource_busy_check(v_task, v_org) LOOP
      v_busy := v_busy || jsonb_build_array(r.conflict);
      v_busy_lines := v_busy_lines || r.line_guids;
    END LOOP;
    IF v_mode = 'capacityModeBlock' AND COALESCE(array_length(v_busy_lines, 1), 0) > 0 THEN
      DELETE FROM public.task_line_plan_movements WHERE "rowParentGUID" = ANY (v_busy_lines);
      v_ids := ARRAY(SELECT x FROM unnest(v_ids) AS x WHERE NOT (x = ANY (v_busy_lines)));
    END IF;
    UPDATE public.task_line_plan_movements SET "planMovementStatus" = true WHERE "rowOwnerGUID" = v_task AND NOT "planMovementStatus";
  END IF;

  -- the timeline: the movements of the task grouped by line and DAY (the start of the day in the zone of the post)
  INSERT INTO public.task_line_plan_timeline ("rowProjectGUID", "rowOwnerGUID", "rowPeriodDatetime", "taskLineGUID", "qtyForBudget", "sumForContract", "sumForBudget", "sumForAccounting")
  SELECT m."rowProjectGUID", m."rowOwnerGUID", date_trunc('day', m."rowPeriodDatetime" AT TIME ZONE v_tz) AT TIME ZONE v_tz, m."rowParentGUID",
         SUM(m."qtyTaskLine"), SUM(m."sumForContract"), SUM(m."sumForBudget"), SUM(m."sumForAccounting")
    FROM public.task_line_plan_movements m
   WHERE m."rowOwnerGUID" = v_task
   GROUP BY m."rowProjectGUID", m."rowOwnerGUID", m."rowParentGUID", date_trunc('day', m."rowPeriodDatetime" AT TIME ZONE v_tz) AT TIME ZONE v_tz;

  -- posted lines: taskIsPosted + the base (a merge, no other key of the line is lost)
  UPDATE public.task_line_table l
     SET "rowJSON" = l."rowJSON" || jsonb_build_object('taskIsPosted', true, 'baseOfDistribution',
           COALESCE((SELECT (x.value->>'baseOfDistribution')::numeric FROM jsonb_array_elements("taskLinePlanJSON"->'lines') x WHERE (x.value->>'lineGUID')::uuid = l."rowGUID"), 1))
   WHERE l."rowGUID" = ANY (v_ids);
  -- a line of the task that was not sent has no days any more (its budget item was cleared): it is not posted
  UPDATE public.task_line_table l
     SET "rowJSON" = (l."rowJSON" - 'baseOfDistribution') || '{"taskIsPosted": false}'::jsonb
   WHERE l."rowOwnerGUID" = v_task AND NOT (l."rowGUID" = ANY (v_ids)) AND jsonb_exists(l."rowJSON", 'baseOfDistribution');

  SELECT count(*) INTO v_rows FROM public.task_line_plan_movements WHERE "rowOwnerGUID" = v_task;
  RETURN jsonb_build_object('lines', COALESCE(array_length(v_ids, 1), 0), 'rows', v_rows, 'mode', v_mode, 'busy', v_busy);
END;
$$;
REVOKE ALL ON FUNCTION public.create_task_line_plan(jsonb) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.create_task_line_plan(jsonb) TO authenticated;

-- -------------------------------------------------------------------------------------
-- The start or the finish DAY of a task changed (the scheduler writes rowJSON.startAt and rowDuration): its posted lines need a new post.
-- A write of the same days (the scheduler runs often) changes nothing.
-- -------------------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.task_line_plan_unpost_on_dates() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, extensions AS $$
BEGIN
  IF (NEW."rowDuration")::date IS DISTINCT FROM (OLD."rowDuration")::date
     OR NULLIF(NEW."rowJSON"->>'startAt', '')::timestamptz::date IS DISTINCT FROM NULLIF(OLD."rowJSON"->>'startAt', '')::timestamptz::date THEN
    UPDATE public.task_line_table l
       SET "rowJSON" = l."rowJSON" || '{"taskIsPosted": false}'::jsonb
     WHERE l."rowOwnerGUID" = NEW."rowGUID" AND l."rowJSON" @> '{"taskIsPosted": true}'::jsonb;
  END IF;
  RETURN NEW;
END;
$$;
DROP TRIGGER IF EXISTS trg_task_line_plan_unpost_on_dates ON public.project_task_table;
CREATE TRIGGER trg_task_line_plan_unpost_on_dates
  AFTER UPDATE OF "rowJSON", "rowDuration" ON public.project_task_table
  FOR EACH ROW EXECUTE FUNCTION public.task_line_plan_unpost_on_dates();

NOTIFY pgrst, 'reload schema';

-- Check (empty is right until the first Post):
--   SELECT count(*) FROM public.task_line_plan_movements;
--   SELECT "rowParentGUID", sum("rowCoefficient"), sum("sumForBudget") FROM public.task_line_plan_movements GROUP BY 1;   -- 1.0000000000 and the line sums


-- ===============================================================================================
-- PART 16: create_user_calendar_tables.sql
-- user calendars, events, reminders
-- ===============================================================================================

-- =====================================================================================
-- UNIVERSAL1 - USER CALENDAR: create_user_calendar_tables.sql
-- (run AFTER create_tables.sql; idempotent - safe to run twice)
--
-- App code: kit8/register/user_calendar (model, CRUD, recurrence, Google sync, reminders,
--           e-mail invitations) + kit8/catalog/user/calendar (screens), route /user/calendar.
--
-- Tables (prefix user_calendar_, kit8/sql/defTable.md pattern, UUID ids, owner RLS):
--   user_calendar_table             the user's calendars ("My calendar", "Tasks", "Birthdays", "Project tasks")
--       rowOwnerGUID  = the user (public.app_user_guid() = userState.userGUID)
--       rowParentGUID = 'empty'
--       rowJSON       = { calendarCode, calendarTitle, calendarColor, isVisible }
--   user_calendar_event_table       events, calendar tasks, birthdays and the copies of project tasks
--       rowOwnerGUID  = the user
--       rowParentGUID = user_calendar_table.rowGUID (text) or 'empty'
--       orderInList   = start, milliseconds since 1970 (ascending = oldest first)
--       rowJSON       = { kind: 'event'|'task'|'birthday'|'projectTask', title, allDay, startAt, endAt,
--                         startDate, endDate, recurrence, exDates, notifications, guests, location,
--                         description, color, done, deadline, googleEventId, intent,
--                         projectGUID, projectTaskGUID, projectTitle, rowProgress }
--   user_calendar_invitation_table  e-mail invitations sent for an event / task / birthday
--       rowOwnerGUID  = the user who invited
--       rowParentGUID = user_calendar_event_table.rowGUID (text)
--       rowJSON       = { email, status: 'sent'|'failed', sentAt, error, resendId }
--
-- PROJECT TASKS: every task / milestone of project_task_table is mirrored automatically into
-- user_calendar_event_table (kind 'projectTask') by triggers: insert, update and sql_for_delete of a
-- project task do the same to its calendar row. The calendar row belongs to the task's owner.
-- =====================================================================================

CREATE TABLE IF NOT EXISTS public.user_calendar_table (
  "rowGUID"       UUID        NOT NULL DEFAULT gen_random_uuid(),
  "rowOwnerGUID"  UUID        NOT NULL,
  "rowParentGUID" TEXT        NOT NULL DEFAULT 'empty',
  "rowJSON"       JSONB       NOT NULL DEFAULT '{}'::jsonb,
  "orderInList"   NUMERIC     NOT NULL DEFAULT 0,
  "created_at"    TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  "updated_at"    TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  PRIMARY KEY ("rowGUID")
);
CREATE INDEX IF NOT EXISTS idx_user_calendar_table_owner ON public.user_calendar_table ("rowOwnerGUID", "orderInList");
-- one calendar of each code per user ("my", "tasks", "birthdays", "projectTasks")
CREATE UNIQUE INDEX IF NOT EXISTS idx_user_calendar_table_owner_code
  ON public.user_calendar_table ("rowOwnerGUID", ("rowJSON"->>'calendarCode'))
  WHERE ("rowJSON"->>'calendarCode') IS NOT NULL;

CREATE TABLE IF NOT EXISTS public.user_calendar_event_table (
  "rowGUID"       UUID        NOT NULL DEFAULT gen_random_uuid(),
  "rowOwnerGUID"  UUID        NOT NULL,
  "rowParentGUID" TEXT        NOT NULL DEFAULT 'empty',
  "rowJSON"       JSONB       NOT NULL DEFAULT '{}'::jsonb,
  "orderInList"   NUMERIC     NOT NULL DEFAULT 0,
  "created_at"    TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  "updated_at"    TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  PRIMARY KEY ("rowGUID")
);
CREATE INDEX IF NOT EXISTS idx_user_calendar_event_owner ON public.user_calendar_event_table ("rowOwnerGUID", "orderInList");
-- one calendar row per project task (the mirror trigger upserts on it)
CREATE UNIQUE INDEX IF NOT EXISTS idx_user_calendar_event_project_task
  ON public.user_calendar_event_table (("rowJSON"->>'projectTaskGUID'))
  WHERE ("rowJSON"->>'projectTaskGUID') IS NOT NULL;
-- one calendar row per Google event per user (Google sync upserts on it)
CREATE UNIQUE INDEX IF NOT EXISTS idx_user_calendar_event_google
  ON public.user_calendar_event_table ("rowOwnerGUID", ("rowJSON"->>'googleEventId'))
  WHERE ("rowJSON"->>'googleEventId') IS NOT NULL;

CREATE TABLE IF NOT EXISTS public.user_calendar_invitation_table (
  "rowGUID"       UUID        NOT NULL DEFAULT gen_random_uuid(),
  "rowOwnerGUID"  UUID        NOT NULL,
  "rowParentGUID" TEXT        NOT NULL DEFAULT 'empty',
  "rowJSON"       JSONB       NOT NULL DEFAULT '{}'::jsonb,
  "orderInList"   NUMERIC     NOT NULL DEFAULT 0,
  "created_at"    TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  "updated_at"    TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  PRIMARY KEY ("rowGUID")
);
CREATE INDEX IF NOT EXISTS idx_user_calendar_invitation_owner ON public.user_calendar_invitation_table ("rowOwnerGUID", "rowParentGUID");

-- ---- updated_at trigger, RLS (every row belongs to app_user_guid()), grants -----------------
DO $$
DECLARE
  t text;
BEGIN
  FOREACH t IN ARRAY ARRAY['user_calendar_table', 'user_calendar_event_table', 'user_calendar_invitation_table'] LOOP
    PERFORM public.kit8_setup_def_table(t);
    EXECUTE format('REVOKE ALL ON public.%I FROM anon, authenticated', t);
    EXECUTE format('GRANT SELECT, INSERT, UPDATE, DELETE ON public.%I TO authenticated', t);
    EXECUTE format('DROP POLICY IF EXISTS %I ON public.%I', t || '_select', t);
    EXECUTE format('DROP POLICY IF EXISTS %I ON public.%I', t || '_insert', t);
    EXECUTE format('DROP POLICY IF EXISTS %I ON public.%I', t || '_update', t);
    EXECUTE format('DROP POLICY IF EXISTS %I ON public.%I', t || '_delete', t);
    EXECUTE format('CREATE POLICY %I ON public.%I FOR SELECT TO authenticated USING ("rowOwnerGUID" = (SELECT public.app_user_guid()))', t || '_select', t);
    EXECUTE format('CREATE POLICY %I ON public.%I FOR INSERT TO authenticated WITH CHECK ("rowOwnerGUID" = (SELECT public.app_user_guid()))', t || '_insert', t);
    EXECUTE format('CREATE POLICY %I ON public.%I FOR UPDATE TO authenticated USING ("rowOwnerGUID" = (SELECT public.app_user_guid())) WITH CHECK ("rowOwnerGUID" = (SELECT public.app_user_guid()))', t || '_update', t);
    EXECUTE format('CREATE POLICY %I ON public.%I FOR DELETE TO authenticated USING ("rowOwnerGUID" = (SELECT public.app_user_guid()))', t || '_delete', t);
  END LOOP;
END $$;

-- =====================================================================================
-- Project tasks -> calendar (automatic create / update / sql_for_delete)
-- =====================================================================================
-- Calendar rowJSON of one project task. Day plans = all-day (the finish is exclusive, so the
-- last day is finish - 1 day); hour / minute / second plans = timed.
CREATE OR REPLACE FUNCTION public.user_calendar_project_task_json(p_task public.project_task_table)
RETURNS jsonb LANGUAGE plpgsql STABLE SET search_path = public, extensions AS $$
DECLARE
  v_project public.project_table%ROWTYPE;
  v_start   timestamptz;
  v_finish  timestamptz;
  v_sub_day boolean;
BEGIN
  SELECT * INTO v_project FROM public.project_table WHERE "rowGUID" = p_task."projectGUID";
  v_start := COALESCE(
    NULLIF(p_task."rowJSON"->>'startAt', '')::timestamptz,
    NULLIF(p_task."rowJSON"->>'manualStartAt', '')::timestamptz,
    NULLIF(v_project."rowJSON"->>'projectStartAt', '')::timestamptz,
    date_trunc('day', NOW() AT TIME ZONE 'UTC') AT TIME ZONE 'UTC');
  v_finish := COALESCE(p_task."rowDuration", v_start);
  IF v_finish < v_start THEN v_finish := v_start; END IF;
  v_sub_day := COALESCE((v_project."rowJSON"->>'planHour')::boolean, false)
            OR COALESCE((v_project."rowJSON"->>'planMinute')::boolean, false)
            OR COALESCE((v_project."rowJSON"->>'planSecond')::boolean, false);
  RETURN jsonb_build_object(
    'kind', 'projectTask',
    'title', COALESCE(NULLIF(p_task."rowJSON"->>'name', ''), 'Task'),
    'allDay', NOT v_sub_day,
    'startAt', to_char(v_start AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"'),
    'endAt', to_char((CASE WHEN v_finish > v_start THEN v_finish ELSE v_start + (CASE WHEN v_sub_day THEN INTERVAL '1 hour' ELSE INTERVAL '1 day' END) END) AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"'),
    'startDate', to_char(v_start AT TIME ZONE 'UTC', 'YYYY-MM-DD'),
    'endDate', to_char((CASE WHEN v_finish > v_start THEN v_finish - INTERVAL '1 second' ELSE v_start END) AT TIME ZONE 'UTC', 'YYYY-MM-DD'),
    'description', COALESCE(p_task."rowJSON"->>'notes', ''),
    'color', p_task."rowJSON"->>'taskColor',
    'rowKind', p_task."rowJSON"->>'rowKind',
    'rowProgress', p_task."rowProgress",
    'done', p_task."rowProgress" >= 100,
    'projectGUID', p_task."projectGUID",
    'projectTaskGUID', p_task."rowGUID",
    'projectTitle', COALESCE(v_project."rowJSON"->>'name', ''),
    'notifications', '[]'::jsonb
  );
END;
$$;

CREATE OR REPLACE FUNCTION public.user_calendar_project_task_sync() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, extensions AS $$
DECLARE
  v_json jsonb;
BEGIN
  IF TG_OP = 'DELETE' THEN
    DELETE FROM public.user_calendar_event_table WHERE "rowJSON"->>'projectTaskGUID' = OLD."rowGUID"::text;
    RETURN OLD;
  END IF;
  -- stages are summary rows: only tasks and milestones are calendar entries
  IF COALESCE(NEW."rowJSON"->>'rowKind', 'task') NOT IN ('task', 'milestone') THEN
    DELETE FROM public.user_calendar_event_table WHERE "rowJSON"->>'projectTaskGUID' = NEW."rowGUID"::text;
    RETURN NEW;
  END IF;
  v_json := public.user_calendar_project_task_json(NEW);
  UPDATE public.user_calendar_event_table e
     -- keep what the user added in the calendar (reminders, guests, Google link ...); the task wins on its own fields
     SET "rowJSON" = e."rowJSON" || (v_json - 'notifications'),
         "rowOwnerGUID" = NEW."rowOwnerGUID",
         "orderInList" = EXTRACT(EPOCH FROM (v_json->>'startAt')::timestamptz) * 1000
   WHERE e."rowJSON"->>'projectTaskGUID' = NEW."rowGUID"::text
     AND (e."rowJSON" || (v_json - 'notifications')) IS DISTINCT FROM e."rowJSON";
  IF NOT EXISTS (SELECT 1 FROM public.user_calendar_event_table e WHERE e."rowJSON"->>'projectTaskGUID' = NEW."rowGUID"::text) THEN
    INSERT INTO public.user_calendar_event_table ("rowOwnerGUID", "rowParentGUID", "orderInList", "rowJSON")
    VALUES (NEW."rowOwnerGUID", 'empty', EXTRACT(EPOCH FROM (v_json->>'startAt')::timestamptz) * 1000, v_json)
    ON CONFLICT DO NOTHING;
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_project_task_zzz_user_calendar ON public.project_task_table;
CREATE TRIGGER trg_project_task_zzz_user_calendar
  AFTER INSERT OR UPDATE OR DELETE ON public.project_task_table
  FOR EACH ROW EXECUTE FUNCTION public.user_calendar_project_task_sync();

-- project renamed / planning units changed -> refresh the calendar rows of its tasks
CREATE OR REPLACE FUNCTION public.user_calendar_project_sync() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, extensions AS $$
BEGIN
  IF (NEW."rowJSON"->>'name') IS DISTINCT FROM (OLD."rowJSON"->>'name')
     OR (NEW."rowJSON"->>'planHour') IS DISTINCT FROM (OLD."rowJSON"->>'planHour')
     OR (NEW."rowJSON"->>'planMinute') IS DISTINCT FROM (OLD."rowJSON"->>'planMinute')
     OR (NEW."rowJSON"->>'planSecond') IS DISTINCT FROM (OLD."rowJSON"->>'planSecond') THEN
    UPDATE public.user_calendar_event_table e
       SET "rowJSON" = e."rowJSON" || (public.user_calendar_project_task_json(t) - 'notifications')
      FROM public.project_task_table t
     WHERE t."projectGUID" = NEW."rowGUID"
       AND e."rowJSON"->>'projectTaskGUID' = t."rowGUID"::text;
  END IF;
  RETURN NEW;
END;
$$;
DROP TRIGGER IF EXISTS trg_project_table_zzz_user_calendar ON public.project_table;
CREATE TRIGGER trg_project_table_zzz_user_calendar
  AFTER UPDATE OF "rowJSON" ON public.project_table
  FOR EACH ROW EXECUTE FUNCTION public.user_calendar_project_sync();

-- ---- backfill: the project tasks that exist already ---------------------------------------
INSERT INTO public.user_calendar_event_table ("rowOwnerGUID", "rowParentGUID", "orderInList", "rowJSON")
SELECT t."rowOwnerGUID", 'empty',
       EXTRACT(EPOCH FROM (j.v->>'startAt')::timestamptz) * 1000, j.v
  FROM public.project_task_table t
  CROSS JOIN LATERAL (SELECT public.user_calendar_project_task_json(t) AS v) j
 WHERE COALESCE(t."rowJSON"->>'rowKind', 'task') IN ('task', 'milestone')
   AND NOT EXISTS (SELECT 1 FROM public.user_calendar_event_table e WHERE e."rowJSON"->>'projectTaskGUID' = t."rowGUID"::text)
ON CONFLICT DO NOTHING;

-- ---- realtime (the calendar refreshes itself in every browser / phone of the user) --------
DO $$
DECLARE
  t text;
  v_all boolean;
BEGIN
  SELECT puballtables INTO v_all FROM pg_publication WHERE pubname = 'supabase_realtime';
  IF NOT FOUND OR v_all THEN RETURN; END IF;
  FOREACH t IN ARRAY ARRAY['user_calendar_table', 'user_calendar_event_table', 'user_calendar_invitation_table'] LOOP
    IF NOT EXISTS (SELECT 1 FROM pg_publication_tables WHERE pubname = 'supabase_realtime' AND schemaname = 'public' AND tablename = t) THEN
      EXECUTE format('ALTER PUBLICATION supabase_realtime ADD TABLE public.%I', t);
    END IF;
  END LOOP;
END $$;

NOTIFY pgrst, 'reload schema';

-- Remove everything again:
--   DROP TRIGGER IF EXISTS trg_project_task_zzz_user_calendar ON public.project_task_table;
--   DROP TRIGGER IF EXISTS trg_project_table_zzz_user_calendar ON public.project_table;
--   DROP FUNCTION IF EXISTS public.user_calendar_project_task_sync(), public.user_calendar_project_sync(),
--                           public.user_calendar_project_task_json(public.project_task_table);
--   DROP TABLE IF EXISTS public.user_calendar_invitation_table, public.user_calendar_event_table, public.user_calendar_table;


-- ===============================================================================================
-- PART 17: create_equipment_tables.sql
-- equipmentTypeTable + equipmentTable (the analog of the person for machines), equipment descriptors / variants, the role type "Equipment Resources", task_line_table.rowJSON.taskResourceKind
-- ===============================================================================================

-- =====================================================================================
-- UNIVERSAL1 - EQUIPMENT: create_equipment_tables.sql
-- (run AFTER everything above; IDEMPOTENT + NON-DESTRUCTIVE - safe to run twice. Remove again with the equipment part of delete_sql_structure.sql.)
--
-- Equipment = a machine or a tool that is booked BY THE HOUR on a Time line of a task, like a person (recommendation/EQUIPMENT_TIME.html).
--   equipmentTypeTable   Heavy machinery · Vehicle    the twin of personTypeTable: a type decides the descriptor sets (Property / Variant) of its equipment
--   equipmentTable       the equipment                rowJSON { equipmentTitle, equipmentCode, equipmentType, equipmentOwnership ('own' | 'rented' | 'leased'),
--                                                              equipmentManufacturer, equipmentModel, equipmentSerialNumber, isActive }
--   rowGUID · rowOwnerGUID ('equipmentTypeCatalog' / 'equipmentCatalog') · rowParentGUID 'empty' · orderInList · rowJSON - the defTable pattern.
--   An equipment has its OWN Properties (what it IS: Engine power 110 kW) and Variants (what it can be BOOKED AS: Heavy, With operator) on the
--   shared descriptor tables: propertyValueTable / variantTable, owner = the equipment; the sets belong to the equipment TYPE.
--   Cost: an equipment has no rates and no contract of its own - the hour is costed by the rate of the RESOURCE ROLE of the line (rolePriceTable).
--
-- Also here:
--   * the role type "Equipment Resources" (genus timeGenus, resourceRoleTypeTable.rowJSON.resourceKind = 'equipment'): the roles an equipment line can book,
--     with their requirements (min. engine power), variants (Heavy, With operator ...) and hourly rates
--   * task_line_table.rowJSON.taskResourceKind = 'person' | 'equipment' (empty = person): a CHECK keeps the value honest and allows an equipment on a Time line only
-- =====================================================================================

DO $$
BEGIN
  IF to_regprocedure('public.kit8_setup_def_table(text)') IS NULL OR to_regclass('public."descriptorGenusTable"') IS NULL OR to_regclass('public."resourceRoleTypeTable"') IS NULL THEN
    RAISE EXCEPTION 'Run the parts above first (kit8_setup_def_table, the descriptor tables, resourceRoleTypeTable)';
  END IF;
END $$;

-- ---- equipmentTypeTable + equipmentTable ---------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public."equipmentTypeTable" (
  "rowGUID"       TEXT        NOT NULL DEFAULT gen_random_uuid()::text,
  "rowOwnerGUID"  TEXT        NOT NULL DEFAULT 'equipmentTypeCatalog',
  "rowParentGUID" TEXT        NOT NULL DEFAULT 'empty',
  "rowJSON"       JSONB       NOT NULL DEFAULT '{}'::jsonb,
  "orderInList"   NUMERIC     NOT NULL DEFAULT 0,
  "created_at"    TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  "updated_at"    TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  PRIMARY KEY ("rowGUID")
);
CREATE INDEX IF NOT EXISTS "idx_equipmentTypeTable_owner_order" ON public."equipmentTypeTable" ("rowOwnerGUID", "orderInList");
SELECT public.kit8_setup_def_table('equipmentTypeTable');

CREATE TABLE IF NOT EXISTS public."equipmentTable" (
  "rowGUID"       TEXT        NOT NULL DEFAULT gen_random_uuid()::text,
  "rowOwnerGUID"  TEXT        NOT NULL DEFAULT 'equipmentCatalog',
  "rowParentGUID" TEXT        NOT NULL DEFAULT 'empty',
  "rowJSON"       JSONB       NOT NULL DEFAULT '{}'::jsonb,
  "orderInList"   NUMERIC     NOT NULL DEFAULT 0,
  "created_at"    TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  "updated_at"    TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  PRIMARY KEY ("rowGUID"),
  CONSTRAINT equipment_ownership_chk CHECK (COALESCE("rowJSON"->>'equipmentOwnership', 'own') IN ('own', 'rented', 'leased'))
);
CREATE INDEX IF NOT EXISTS "idx_equipmentTable_title" ON public."equipmentTable" ((lower("rowJSON"->>'equipmentTitle')));
CREATE INDEX IF NOT EXISTS "idx_equipmentTable_type" ON public."equipmentTable" (("rowJSON"->>'equipmentType'));
CREATE UNIQUE INDEX IF NOT EXISTS "idx_equipmentTable_code" ON public."equipmentTable" (lower("rowJSON"->>'equipmentCode')) WHERE NOT coalesce("rowJSON"->>'equipmentCode', '') = '';
SELECT public.kit8_setup_def_table('equipmentTable');

-- access: signed-in users (as personTable / personTypeTable)
DO $$
DECLARE
  t text;
BEGIN
  FOREACH t IN ARRAY ARRAY['equipmentTypeTable', 'equipmentTable'] LOOP
    EXECUTE format('REVOKE ALL ON public.%I FROM anon, authenticated', t);
    EXECUTE format('GRANT SELECT, INSERT, UPDATE, DELETE ON public.%I TO authenticated', t);
    EXECUTE format('DROP POLICY IF EXISTS %I ON public.%I', t || '_select', t);
    EXECUTE format('DROP POLICY IF EXISTS %I ON public.%I', t || '_insert', t);
    EXECUTE format('DROP POLICY IF EXISTS %I ON public.%I', t || '_update', t);
    EXECUTE format('DROP POLICY IF EXISTS %I ON public.%I', t || '_delete', t);
    EXECUTE format('CREATE POLICY %I ON public.%I FOR SELECT TO authenticated USING (true)', t || '_select', t);
    EXECUTE format('CREATE POLICY %I ON public.%I FOR INSERT TO authenticated WITH CHECK (true)', t || '_insert', t);
    EXECUTE format('CREATE POLICY %I ON public.%I FOR UPDATE TO authenticated USING (true) WITH CHECK (true)', t || '_update', t);
    EXECUTE format('CREATE POLICY %I ON public.%I FOR DELETE TO authenticated USING (true)', t || '_delete', t);
  END LOOP;
END $$;

-- ---- task_line_table.rowJSON.taskResourceKind = 'person' | 'equipment' (empty = person) -------------------------------------------
-- a CHECK keeps the value honest and allows an equipment on a Time line only; every line made before equipment has no kind and passes
DO $$
BEGIN
  IF to_regclass('public.task_line_table') IS NOT NULL AND NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'task_line_resource_kind_chk' AND conrelid = 'public.task_line_table'::regclass) THEN
    ALTER TABLE public.task_line_table ADD CONSTRAINT task_line_resource_kind_chk CHECK (
      COALESCE("rowJSON"->>'taskResourceKind', 'person') IN ('person', 'equipment')
      AND (COALESCE("rowJSON"->>'taskResourceKind', 'person') = 'person' OR "rowParentGUID" = 'timeGenus'));
  END IF;
END $$;

-- ---- realtime ------------------------------------------------------------------------------------------------------------------
DO $$
DECLARE
  t text;
  v_all boolean;
BEGIN
  SELECT puballtables INTO v_all FROM pg_publication WHERE pubname = 'supabase_realtime';
  IF NOT FOUND THEN
    RAISE NOTICE 'publication supabase_realtime does not exist - realtime auto refresh is off';
  ELSIF NOT v_all THEN
    FOREACH t IN ARRAY ARRAY['equipmentTypeTable', 'equipmentTable'] LOOP
      IF NOT EXISTS (SELECT 1 FROM pg_publication_tables WHERE pubname = 'supabase_realtime' AND schemaname = 'public' AND tablename = t) THEN
        EXECUTE format('ALTER PUBLICATION supabase_realtime ADD TABLE public.%I', t);
      END IF;
    END LOOP;
  END IF;
END $$;

NOTIFY pgrst, 'reload schema';

-- Check:
--   SELECT t."rowJSON"->>'title' AS type, count(e.*) AS equipment FROM public."equipmentTypeTable" t LEFT JOIN public."equipmentTable" e ON e."rowJSON"->>'equipmentType' = t."rowGUID" GROUP BY 1;
--   SELECT e."rowJSON"->>'equipmentTitle', v."rowJSON"->>'title' FROM public."equipmentTable" e JOIN public."variantTable" v ON v."rowOwnerGUID" = e."rowGUID" ORDER BY 1, 2;
--   SELECT r."rowJSON"->>'title', pv."rowJSON"->>'value' AS min_power_kw FROM public."resourceRoleTable" r JOIN public."propertyValueTable" pv ON pv."rowOwnerGUID" = r."rowGUID" WHERE r."rowOwnerGUID" = 'equipmentResources';


-- ===============================================================================================
-- PART 18: create_business_unit_tables.sql
-- cfrTypeTable (the enumeration of the Centers of Financial Responsibility) + businessUnitTable (a tree of any depth) + the checks of businessUnitAssigned + the unit on the posted days
-- ===============================================================================================

-- =====================================================================================
-- UNIVERSAL1 - BUSINESS UNITS: create_business_unit_tables.sql
-- (run AFTER parts 1-17; IDEMPOTENT + NON-DESTRUCTIVE: CREATE ... IF NOT EXISTS, seeds ON CONFLICT. Remove again with PART 1b of delete_sql_structure.sql.)
-- Design: documents/BUSINESS_UNIT_CFR_STRUCTURE.html (document "W1 businessUnit").
--
-- cfrTypeTable - the ENUMERATION "Centers Of Financial Responsibility" (works like a 1C enumeration): a flat table of 4 fixed values, written by this file ONLY.
--   rowGUID = the code: costCenter · revenueCenter · profitCenter · investmentCenter   rowOwnerGUID 'cfrTypeCatalog'   rowParentGUID 'empty'
--   rowJSON { title, description, acceptsCosts, acceptsRevenues }  - the rule "which center takes which budget kind" lives HERE, SQL and the app read the same flags.
--   Signed-in users can only READ it (no INSERT / UPDATE / DELETE privilege, no policy) and a trigger refuses a write from any role but postgres / supabase_admin.
--
-- businessUnitTable - the business units, ONE table, a tree of any depth (an enterprise is a root: rowParentGUID 'empty'):
--   rowGUID (text) · rowOwnerGUID 'businessUnitCatalog' · rowParentGUID = the parent unit | 'empty' · orderInList · rowJSON { title, code, description, cfrAssigned, isActive }
--   rowJSON.cfrAssigned = cfrTypeTable.rowGUID (optional). EFFECTIVE CFR of a unit = its own cfrAssigned, else the nearest ancestor's, else none (kit8_business_unit_cfr).
--   Guards: the parent exists, no loop, cfrAssigned exists, a unit with children or in use is not deleted (deactivate it: isActive false), and a CFR change that
--   would contradict days already posted on the unit is refused.
--
-- rowJSON.businessUnitAssigned (the default unit) on budgetItemTable, resourceRoleTable, contractTable, personTable, equipmentTable, productTable; the four project
-- fields projectCostCenter / projectRevenueCenter / projectProfitCenter / projectInvestmentCenter on project_table; businessUnitTaskLine on task_line_table:
-- every one must be an existing unit (kit8_check_business_unit_ref); the project fields must be of the right kind (cost accepts costs, revenue accepts revenues,
-- profit = profitCenter, investment = investmentCenter).
-- The POSTED days (task_line_plan_movements.rowJSON) carry businessUnitAssigned + budgetKind ('cost' | 'revenue'); create_task_line_plan refuses a line whose unit
-- does not accept its kind (a cost on a revenue center, a revenue on a cost center) - see PART 15.
-- =====================================================================================

DO $$
BEGIN
  IF to_regclass('public.task_line_plan_movements') IS NULL OR to_regclass('public."budgetItemTable"') IS NULL OR to_regclass('public."equipmentTable"') IS NULL THEN
    RAISE EXCEPTION 'Run parts 1-17 first (business units point at the task lines, the budget items and the equipment)';
  END IF;
END $$;

-- ---- cfrTypeTable: the enumeration ----------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public."cfrTypeTable" (
  "rowGUID"       TEXT        NOT NULL,
  "rowOwnerGUID"  TEXT        NOT NULL DEFAULT 'cfrTypeCatalog',
  "rowParentGUID" TEXT        NOT NULL DEFAULT 'empty',
  "rowJSON"       JSONB       NOT NULL DEFAULT '{}'::jsonb,
  "orderInList"   NUMERIC     NOT NULL DEFAULT 0,
  "created_at"    TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  "updated_at"    TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  PRIMARY KEY ("rowGUID")
);
SELECT public.kit8_setup_def_table('cfrTypeTable');

-- the enumeration is written by this file only (an app user has no privilege anyway; service_role is refused here)
CREATE OR REPLACE FUNCTION public.kit8_cfr_type_readonly() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF current_user NOT IN ('postgres', 'supabase_admin') THEN
    RAISE EXCEPTION 'cfrTypeTable is an enumeration: its values are fixed (nobody adds, changes or deletes them at run time)';
  END IF;
  IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END;
$$;
DROP TRIGGER IF EXISTS "trg_cfrTypeTable_readonly" ON public."cfrTypeTable";
CREATE TRIGGER "trg_cfrTypeTable_readonly" BEFORE INSERT OR UPDATE OR DELETE ON public."cfrTypeTable"
  FOR EACH ROW EXECUTE FUNCTION public.kit8_cfr_type_readonly();

DO $$
DECLARE
  t text := 'cfrTypeTable';
BEGIN
  EXECUTE format('REVOKE ALL ON public.%I FROM anon, authenticated', t);
  EXECUTE format('GRANT SELECT ON public.%I TO authenticated', t);
  EXECUTE format('DROP POLICY IF EXISTS %I ON public.%I', t || '_select', t);
  EXECUTE format('CREATE POLICY %I ON public.%I FOR SELECT TO authenticated USING (true)', t || '_select', t);
END $$;

-- (the 4 values of the enumeration: start5_sql_upsert_all.sql)

-- does a center of this CFR take a line of this kind? null CFR (a unit with none up the tree) / null kind = yes (nothing to check)
CREATE OR REPLACE FUNCTION public.kit8_cfr_accepts(p_cfr text, p_kind text) RETURNS boolean
LANGUAGE sql STABLE AS $$
  SELECT CASE
    WHEN p_cfr IS NULL OR p_kind IS NULL THEN true
    ELSE COALESCE((SELECT CASE p_kind WHEN 'cost' THEN (c."rowJSON"->>'acceptsCosts')::boolean
                                      WHEN 'revenue' THEN (c."rowJSON"->>'acceptsRevenues')::boolean END
                      FROM public."cfrTypeTable" c WHERE c."rowGUID" = p_cfr), false)
  END;
$$;

-- ---- businessUnitTable ------------------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public."businessUnitTable" (
  "rowGUID"       TEXT        NOT NULL DEFAULT gen_random_uuid()::text,
  "rowOwnerGUID"  TEXT        NOT NULL DEFAULT 'businessUnitCatalog',
  "rowParentGUID" TEXT        NOT NULL DEFAULT 'empty',
  "rowJSON"       JSONB       NOT NULL DEFAULT '{}'::jsonb,
  "orderInList"   NUMERIC     NOT NULL DEFAULT 0,
  "created_at"    TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  "updated_at"    TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  PRIMARY KEY ("rowGUID")
);
CREATE INDEX IF NOT EXISTS "idx_businessUnitTable_owner_order" ON public."businessUnitTable" ("rowOwnerGUID", "orderInList");
CREATE INDEX IF NOT EXISTS "idx_businessUnitTable_parent" ON public."businessUnitTable" ("rowParentGUID");
CREATE INDEX IF NOT EXISTS "idx_businessUnitTable_cfr" ON public."businessUnitTable" ((("rowJSON"->>'cfrAssigned')));
SELECT public.kit8_setup_def_table('businessUnitTable');

-- the effective CFR of a unit: its own, else the nearest ancestor's, else null
CREATE OR REPLACE FUNCTION public.kit8_business_unit_cfr(p_unit text) RETURNS text
LANGUAGE sql STABLE AS $$
  WITH RECURSIVE up AS (
    SELECT b."rowGUID", b."rowParentGUID", NULLIF(b."rowJSON"->>'cfrAssigned', '') AS cfr, 0 AS depth
      FROM public."businessUnitTable" b WHERE b."rowGUID" = p_unit
    UNION ALL
    SELECT b."rowGUID", b."rowParentGUID", NULLIF(b."rowJSON"->>'cfrAssigned', ''), up.depth + 1
      FROM public."businessUnitTable" b JOIN up ON b."rowGUID" = up."rowParentGUID" WHERE up.depth < 200
  )
  SELECT cfr FROM up WHERE cfr IS NOT NULL ORDER BY depth LIMIT 1;
$$;

-- where is a unit used? (text of the first place found, null = nowhere): the guard of the delete
CREATE OR REPLACE FUNCTION public.kit8_business_unit_used(p_unit text) RETURNS text
LANGUAGE plpgsql STABLE AS $$
DECLARE
  t text;
  v_hit boolean;
BEGIN
  IF EXISTS (SELECT 1 FROM public."businessUnitTable" c WHERE c."rowParentGUID" = p_unit) THEN RETURN 'it has sub-units'; END IF;
  IF EXISTS (SELECT 1 FROM public.task_line_table l WHERE l."rowJSON"->>'businessUnitTaskLine' = p_unit) THEN RETURN 'a task line uses it'; END IF;
  IF EXISTS (SELECT 1 FROM public.task_line_plan_movements m WHERE m."rowJSON"->>'businessUnitAssigned' = p_unit) THEN RETURN 'posted days carry it'; END IF;
  IF EXISTS (SELECT 1 FROM public.project_table p WHERE p."rowJSON"->>'projectCostCenter' = p_unit OR p."rowJSON"->>'projectRevenueCenter' = p_unit
                                                     OR p."rowJSON"->>'projectProfitCenter' = p_unit OR p."rowJSON"->>'projectInvestmentCenter' = p_unit) THEN RETURN 'a project uses it'; END IF;
  FOREACH t IN ARRAY ARRAY['budgetItemTable', 'resourceRoleTable', 'contractTable', 'personTable', 'equipmentTable', 'productTable'] LOOP
    EXECUTE format('SELECT EXISTS (SELECT 1 FROM public.%I WHERE "rowJSON"->>''businessUnitAssigned'' = $1)', t) INTO v_hit USING p_unit;
    IF v_hit THEN RETURN t || ' uses it'; END IF;
  END LOOP;
  RETURN NULL;
END;
$$;

-- guards of a unit: the parent exists, no loop, cfrAssigned exists, and a new CFR must not contradict days already posted on the unit
CREATE OR REPLACE FUNCTION public.kit8_business_unit_guard() RETURNS trigger
LANGUAGE plpgsql AS $$
DECLARE
  v_cfr text;
  v_bad integer;
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF public.kit8_business_unit_used(OLD."rowGUID") IS NOT NULL THEN
      RAISE EXCEPTION 'businessUnitTable %: not deleted, %. Deactivate it instead (isActive = false).', OLD."rowGUID", public.kit8_business_unit_used(OLD."rowGUID");
    END IF;
    RETURN OLD;
  END IF;

  IF NEW."rowParentGUID" <> 'empty' THEN
    IF NEW."rowParentGUID" = NEW."rowGUID" THEN
      RAISE EXCEPTION 'businessUnitTable %: a unit cannot be its own parent', NEW."rowGUID";
    END IF;
    IF NOT EXISTS (SELECT 1 FROM public."businessUnitTable" p WHERE p."rowGUID" = NEW."rowParentGUID") THEN
      RAISE EXCEPTION 'businessUnitTable %: the parent "%" does not exist', NEW."rowGUID", NEW."rowParentGUID";
    END IF;
    IF EXISTS (
      WITH RECURSIVE up AS (
        SELECT b."rowGUID", b."rowParentGUID", 1 AS depth FROM public."businessUnitTable" b WHERE b."rowGUID" = NEW."rowParentGUID"
        UNION ALL
        SELECT b."rowGUID", b."rowParentGUID", up.depth + 1 FROM public."businessUnitTable" b JOIN up ON b."rowGUID" = up."rowParentGUID" WHERE up.depth < 200
      ) SELECT 1 FROM up WHERE up."rowGUID" = NEW."rowGUID"
    ) THEN
      RAISE EXCEPTION 'businessUnitTable %: the parent "%" is below this unit (a loop)', NEW."rowGUID", NEW."rowParentGUID";
    END IF;
  END IF;

  v_cfr := NULLIF(NEW."rowJSON"->>'cfrAssigned', '');
  IF v_cfr IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public."cfrTypeTable" c WHERE c."rowGUID" = v_cfr) THEN
    RAISE EXCEPTION 'businessUnitTable %: cfrAssigned "%" is not a value of cfrTypeTable', NEW."rowGUID", v_cfr;
  END IF;

  -- a CFR that no longer takes the kind of days already posted on this unit
  IF TG_OP = 'UPDATE' AND (NEW."rowJSON"->>'cfrAssigned') IS DISTINCT FROM (OLD."rowJSON"->>'cfrAssigned') AND v_cfr IS NOT NULL THEN
    SELECT count(*) INTO v_bad FROM public.task_line_plan_movements m
     WHERE m."rowJSON"->>'businessUnitAssigned' = NEW."rowGUID" AND NOT public.kit8_cfr_accepts(v_cfr, m."rowJSON"->>'budgetKind');
    IF v_bad > 0 THEN
      RAISE EXCEPTION 'businessUnitTable %: % posted day(s) of this unit are of a kind the % does not take', NEW."rowGUID", v_bad, v_cfr;
    END IF;
  END IF;
  RETURN NEW;
END;
$$;
DROP TRIGGER IF EXISTS "trg_businessUnitTable_guard" ON public."businessUnitTable";
CREATE TRIGGER "trg_businessUnitTable_guard" BEFORE INSERT OR UPDATE OR DELETE ON public."businessUnitTable"
  FOR EACH ROW EXECUTE FUNCTION public.kit8_business_unit_guard();

DO $$
DECLARE
  t text := 'businessUnitTable';
BEGIN
  EXECUTE format('REVOKE ALL ON public.%I FROM anon, authenticated', t);
  EXECUTE format('GRANT SELECT, INSERT, UPDATE, DELETE ON public.%I TO authenticated', t);
  EXECUTE format('DROP POLICY IF EXISTS %I ON public.%I', t || '_select', t);
  EXECUTE format('DROP POLICY IF EXISTS %I ON public.%I', t || '_insert', t);
  EXECUTE format('DROP POLICY IF EXISTS %I ON public.%I', t || '_update', t);
  EXECUTE format('DROP POLICY IF EXISTS %I ON public.%I', t || '_delete', t);
  EXECUTE format('CREATE POLICY %I ON public.%I FOR SELECT TO authenticated USING (true)', t || '_select', t);
  EXECUTE format('CREATE POLICY %I ON public.%I FOR INSERT TO authenticated WITH CHECK (true)', t || '_insert', t);
  EXECUTE format('CREATE POLICY %I ON public.%I FOR UPDATE TO authenticated USING (true) WITH CHECK (true)', t || '_update', t);
  EXECUTE format('CREATE POLICY %I ON public.%I FOR DELETE TO authenticated USING (true)', t || '_delete', t);
END $$;

-- ---- the example company of the document "W1 businessUnit": 29 units, 4 levels, 9 with a CFR (the others inherit; Enterprise #1 = investment center) --------------
-- fixed codes (bu_...) so the demo tree and the tests are repeatable; parents before children
-- (the 29 example units: start5_sql_upsert_all.sql)

-- ---- businessUnitAssigned on the six catalogs, the line and the project: an existing unit, of the right kind -------------------------------------------------
-- trigger arguments: 'key' = the unit must exist · 'key:cost' / 'key:revenue' = ... and its effective CFR must take that kind · 'key=profitCenter' = ... and be exactly that CFR
CREATE OR REPLACE FUNCTION public.kit8_check_business_unit_ref() RETURNS trigger
LANGUAGE plpgsql AS $$
DECLARE
  a text;
  v_key text;
  v_unit text;
  v_cfr text;
BEGIN
  FOREACH a IN ARRAY TG_ARGV LOOP
    v_key := split_part(split_part(a, ':', 1), '=', 1);
    v_unit := NULLIF(NEW."rowJSON"->>v_key, '');
    CONTINUE WHEN v_unit IS NULL OR v_unit = 'empty';
    IF NOT EXISTS (SELECT 1 FROM public."businessUnitTable" b WHERE b."rowGUID" = v_unit) THEN
      RAISE EXCEPTION '%.rowJSON.%: "%" is not a business unit', TG_TABLE_NAME, v_key, v_unit;
    END IF;
    v_cfr := public.kit8_business_unit_cfr(v_unit);
    IF position(':' IN a) > 0 AND NOT public.kit8_cfr_accepts(v_cfr, split_part(a, ':', 2)) THEN
      RAISE EXCEPTION '%.rowJSON.%: the unit "%" (%) does not take %s', TG_TABLE_NAME, v_key, v_unit, v_cfr, split_part(a, ':', 2);
    END IF;
    IF position('=' IN a) > 0 AND v_cfr IS DISTINCT FROM split_part(a, '=', 2) THEN
      RAISE EXCEPTION '%.rowJSON.%: the unit "%" must be a % (it is %)', TG_TABLE_NAME, v_key, v_unit, split_part(a, '=', 2), COALESCE(v_cfr, 'without a CFR');
    END IF;
  END LOOP;
  RETURN NEW;
END;
$$;

DO $$
DECLARE
  t text;
BEGIN
  FOREACH t IN ARRAY ARRAY['budgetItemTable', 'resourceRoleTable', 'contractTable', 'personTable', 'equipmentTable', 'productTable'] LOOP
    EXECUTE format('DROP TRIGGER IF EXISTS %I ON public.%I', 'trg_' || t || '_business_unit', t);
    EXECUTE format('CREATE TRIGGER %I BEFORE INSERT OR UPDATE OF "rowJSON" ON public.%I FOR EACH ROW EXECUTE FUNCTION public.kit8_check_business_unit_ref(%L)',
                   'trg_' || t || '_business_unit', t, 'businessUnitAssigned');
  END LOOP;
END $$;
DROP TRIGGER IF EXISTS trg_task_line_table_business_unit ON public.task_line_table;
CREATE TRIGGER trg_task_line_table_business_unit BEFORE INSERT OR UPDATE OF "rowJSON" ON public.task_line_table
  FOR EACH ROW EXECUTE FUNCTION public.kit8_check_business_unit_ref('businessUnitTaskLine');
DROP TRIGGER IF EXISTS trg_project_table_business_unit ON public.project_table;
CREATE TRIGGER trg_project_table_business_unit BEFORE INSERT OR UPDATE OF "rowJSON" ON public.project_table
  FOR EACH ROW EXECUTE FUNCTION public.kit8_check_business_unit_ref('projectCostCenter:cost', 'projectRevenueCenter:revenue', 'projectProfitCenter=profitCenter', 'projectInvestmentCenter=investmentCenter');

-- realtime
DO $$
DECLARE
  t text;
  v_all boolean;
BEGIN
  SELECT puballtables INTO v_all FROM pg_publication WHERE pubname = 'supabase_realtime';
  IF NOT FOUND THEN
    RAISE NOTICE 'publication supabase_realtime does not exist - realtime auto refresh is off';
  ELSIF NOT v_all THEN
    FOREACH t IN ARRAY ARRAY['cfrTypeTable', 'businessUnitTable'] LOOP
      IF NOT EXISTS (SELECT 1 FROM pg_publication_tables WHERE pubname = 'supabase_realtime' AND schemaname = 'public' AND tablename = t) THEN
        EXECUTE format('ALTER PUBLICATION supabase_realtime ADD TABLE public.%I', t);
      END IF;
    END LOOP;
  END IF;
END $$;

